    if not game:IsLoaded() then game.Loaded:Wait() end
    local bootstrapPlayers = game:GetService("Players")
    local bootstrapPlayer = bootstrapPlayers.LocalPlayer
    local deadline = tick() + 10
    while not bootstrapPlayer and tick() < deadline do
        task.wait(0.1)
        bootstrapPlayer = bootstrapPlayers.LocalPlayer
    end

    local bootstrapParent = nil
    pcall(function()
        if type(gethui) == "function" then bootstrapParent = gethui() end
    end)
    if not bootstrapParent then
        bootstrapParent = bootstrapPlayer and bootstrapPlayer:WaitForChild("PlayerGui", 10)
    end
