local function __lrrxMain()
__lrrxSetStage("02  Resolving executor APIs...", false)

local function GetExecutorGlobal(name)
    local value = nil
    pcall(function()
        local env = (type(getgenv) == "function" and getgenv()) or _G
        value = env and env[name]
    end)
    if value == nil then pcall(function() value = _G[name] end) end
    return value
end

local nativeGetHui = GetExecutorGlobal("gethui")

local function SafeCloneRef(object)
    -- Plain service references are the most reliable option on Xeno.
    -- Keeping this wrapper lets stronger executors be supported without requiring cloneref.
    return object
end

local function SafeGetService(name)
    local ok, service = pcall(function() return game:GetService(name) end)
    if ok and service then return SafeCloneRef(service) end
    return nil
end

local HttpService = SafeGetService("HttpService")
local CoreGui = SafeGetService("CoreGui")
local Players = SafeGetService("Players")
local VirtualInputManager = SafeGetService("VirtualInputManager")
local UserInputService = SafeGetService("UserInputService")
local RunService = SafeGetService("RunService")
local TweenService = SafeGetService("TweenService")
local LogService = SafeGetService("LogService")
__lrrxSetStage("03  Services ready; loading settings...", false)

local function ResolveRequestFunction()
    local directNames = {"request", "http_request", "httprequest", "krnl_request"}
    for _, name in ipairs(directNames) do
        local candidate = GetExecutorGlobal(name)
        if type(candidate) == "function" then return candidate end
    end

    for _, tableName in ipairs({"syn", "http", "fluxus"}) do
        local container = GetExecutorGlobal(tableName)
        if type(container) == "table" and type(container.request) == "function" then
            return container.request
        end
    end
    return nil
end

local request = ResolveRequestFunction()
local executorWriteFile = GetExecutorGlobal("writefile")
local executorReadFile = GetExecutorGlobal("readfile")
local executorIsFile = GetExecutorGlobal("isfile")

local function ParentGuiSafely(gui)
    local candidates = {}
    local player = Players.LocalPlayer
    local playerGui = player and (player:FindFirstChildOfClass("PlayerGui") or player:WaitForChild("PlayerGui", 5))
    if type(nativeGetHui) == "function" then
        local ok, result = pcall(nativeGetHui)
        if ok and result then table.insert(candidates, result) end
    end
    if CoreGui then table.insert(candidates, CoreGui) end
    if playerGui then table.insert(candidates, playerGui) end

    for _, candidate in ipairs(candidates) do
        local ok = pcall(function() gui.Parent = candidate end)
        if ok and gui.Parent == candidate then return candidate end
    end
    return nil
end

