local function SaveConfig()
    if type(executorWriteFile) == "function" then
        pcall(executorWriteFile, ConfigFile, HttpService:JSONEncode(Config))
    end
end

local function LoadConfig()
    if type(executorIsFile) == "function" and type(executorReadFile) == "function" then
        local existsOk, exists = pcall(executorIsFile, ConfigFile)
        if existsOk and exists then
            local success, decoded = pcall(function()
                return HttpService:JSONDecode(executorReadFile(ConfigFile))
            end)
            if success and decoded then
                for k, v in pairs(decoded) do Config[k] = v end
            end
        end
    end
end
LoadConfig()

-- V11 replaces the old palette-only themes with complete visual worlds. This
-- one-time migration turns on the requested angel scene, while keeping the
-- visible switch available so it can be disabled at any time.
if not Config.VisualWorldV11 then
    if Config.ThemeMode == "Seraph" or Config.ThemeMode == "Pearl" or Config.ThemeMode == "Dawn" then
        Config.ThemeMode = "Heavenly Garden"
    end
    Config.ShowAngel = true
    Config.SmoothBoot = true
    Config.VisualWorldV11 = true
    SaveConfig()
end

