-- Older saved configurations do not have the Spam workspace yet. Keep only
-- clean, unique endings so malformed executor JSON cannot disturb the scanner.
do
    if type(Config.SpamEndings) ~= "table" then Config.SpamEndings = {} end
    local cleanEndings = {}
    local seenEndings = {}
    for _, rawEnding in ipairs(Config.SpamEndings) do
        local ending = tostring(rawEnding or ""):lower():gsub("’", "'"):gsub("[^a-z'%-]", "")
        if #ending > 0 and #ending <= 18 and not seenEndings[ending] then
            seenEndings[ending] = true
            table.insert(cleanEndings, ending)
        end
    end
    Config.SpamEndings = cleanEndings
end

