    Highway = {Word = Enum.Font.Highway, Heading = Enum.Font.Highway, Body = Enum.Font.Gotham},
    Soft = {Word = Enum.Font.SourceSansSemibold, Heading = Enum.Font.SourceSansBold, Body = Enum.Font.SourceSans}
}
Config.FontStyle = tostring(Config.FontStyle or "Celestial")
if not AuxUI.FontProfiles[Config.FontStyle] then Config.FontStyle = "Celestial" end
AuxUI.GetFontProfile = function()
    return AuxUI.FontProfiles[Config.FontStyle] or AuxUI.FontProfiles.Celestial
end

-- Normalize every source (HUD tiles, logs, search, and custom words) through
-- one punctuation-safe path. Several fonts render a hyphen as a Unicode dash;
-- treating those as ASCII prevents visually identical prompts from missing.
AuxUI.NormalizeWordText = function(value)
    return tostring(value or ""):lower()
        :gsub("’", "'"):gsub("‘", "'")
        :gsub("‐", "-"):gsub("‑", "-"):gsub("–", "-"):gsub("—", "-"):gsub("−", "-")
        :gsub("[%s%c]+", "")
end

-- The portrait is bundled as a compact PNG so a pasted script still contains
-- its actual artwork. Roblox ImageLabels cannot read data URLs, therefore the
-- bytes are materialized once and registered through the executor's supported
-- custom-asset bridge. The entire interface remains functional without it.
do
    local EMBEDDED_GUARDIAN_PNG = [[]]
    local function DecodeBase64(data)
        local characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local lookup = {}
        for index = 1, #characters do
            lookup[string.byte(characters, index)] = index - 1
        end

        local output = {}
        local segment = {}
        for index = 1, #data, 4 do
            local aByte = string.byte(data, index)
            local bByte = string.byte(data, index + 1)
            local cByte = string.byte(data, index + 2)
            local dByte = string.byte(data, index + 3)
            local cPadding = cByte == nil or cByte == 61
            local dPadding = dByte == nil or dByte == 61
            local a = lookup[aByte] or 0
            local b = lookup[bByte] or 0
            local c = cPadding and 0 or (lookup[cByte] or 0)
            local d = dPadding and 0 or (lookup[dByte] or 0)
            local packed = a * 262144 + b * 4096 + c * 64 + d
            segment[#segment + 1] = string.char(math.floor(packed / 65536) % 256)
            if not cPadding then segment[#segment + 1] = string.char(math.floor(packed / 256) % 256) end
            if not dPadding then segment[#segment + 1] = string.char(packed % 256) end
            if #segment >= 2048 then
                output[#output + 1] = table.concat(segment)
                segment = {}
            end
        end
        if #segment > 0 then output[#output + 1] = table.concat(segment) end
        return table.concat(output)
    end

    local configuredSource = tostring(Config.BootAngelAsset or "")
    if configuredSource:match("^%d+$") then configuredSource = "rbxassetid://" .. configuredSource end
    local assetGetter = GetExecutorGlobal("getcustomasset") or GetExecutorGlobal("getsynasset") or GetExecutorGlobal("getasset")

    local function RegisterLocalAsset(path)
        if type(assetGetter) ~= "function" or type(path) ~= "string" or path == "" then return nil end
        if type(executorIsFile) == "function" then
            local existsOk, exists = pcall(executorIsFile, path)
            if not existsOk or not exists then return nil end
        end
        local ok, asset = pcall(assetGetter, path)
        if ok and asset then return tostring(asset) end
        return nil
    end

    if configuredSource:match("^rbxasset") then
        AuxUI.GuardianAsset = configuredSource
    elseif configuredSource ~= "" then
        AuxUI.GuardianAsset = RegisterLocalAsset(configuredSource)
    end

    if not AuxUI.GuardianAsset then
        AuxUI.GuardianAsset = RegisterLocalAsset(tostring(Config.BootAngelFile or "LRRXWARE_Guardian_V12.png"))
    end

    if not AuxUI.GuardianAsset and type(executorWriteFile) == "function" and type(assetGetter) == "function" then
        local embeddedPath = "LRRXWARE_Guardian_V12.png"
        local writeOk = pcall(executorWriteFile, embeddedPath, DecodeBase64(EMBEDDED_GUARDIAN_PNG))
        if writeOk then
            AuxUI.GuardianAsset = RegisterLocalAsset(embeddedPath)
            AuxUI.GuardianEmbedded = AuxUI.GuardianAsset ~= nil
        else
            AuxUI.GuardianFailure = "executor refused the embedded portrait file"
        end
    end

    if not AuxUI.GuardianAsset then
        AuxUI.GuardianFailure = AuxUI.GuardianFailure or "custom images are unavailable in this executor"
    end
end

-- The lexicon receives its own lightweight guardian pose. It is embedded
-- separately so opening the definition panel performs no network image load.
do
    local EMBEDDED_LEXICON_GUARDIAN_PNG = [[]]
    local function DecodeLexiconBase64(data)
        local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local lookup = {}
        for index = 1, #alphabet do lookup[string.byte(alphabet, index)] = index - 1 end
        local output, segment = {}, {}
        for index = 1, #data, 4 do
            local aByte, bByte = string.byte(data, index), string.byte(data, index + 1)
            local cByte, dByte = string.byte(data, index + 2), string.byte(data, index + 3)
            local cPadding, dPadding = cByte == nil or cByte == 61, dByte == nil or dByte == 61
            local packed = (lookup[aByte] or 0) * 262144 + (lookup[bByte] or 0) * 4096
                + (cPadding and 0 or (lookup[cByte] or 0)) * 64
                + (dPadding and 0 or (lookup[dByte] or 0))
            segment[#segment + 1] = string.char(math.floor(packed / 65536) % 256)
            if not cPadding then segment[#segment + 1] = string.char(math.floor(packed / 256) % 256) end
            if not dPadding then segment[#segment + 1] = string.char(packed % 256) end
            if #segment >= 2048 then output[#output + 1], segment = table.concat(segment), {} end
        end
        if #segment > 0 then output[#output + 1] = table.concat(segment) end
        return table.concat(output)
    end

    local assetGetter = GetExecutorGlobal("getcustomasset") or GetExecutorGlobal("getsynasset") or GetExecutorGlobal("getasset")
    local function RegisterLexiconAsset(path)
        if type(assetGetter) ~= "function" then return nil end
        if type(executorIsFile) == "function" then
            local ok, exists = pcall(executorIsFile, path)
            if not ok or not exists then return nil end
        end
        local ok, asset = pcall(assetGetter, path)
        return ok and asset and tostring(asset) or nil
    end

    local lexiconPath = "LRRXWARE_Lexicon_Guardian_V13.png"
    AuxUI.LexiconGuardianAsset = RegisterLexiconAsset(lexiconPath)
    if not AuxUI.LexiconGuardianAsset and type(executorWriteFile) == "function" and type(assetGetter) == "function" then
        local ok = pcall(executorWriteFile, lexiconPath, DecodeLexiconBase64(EMBEDDED_LEXICON_GUARDIAN_PNG))
        if ok then AuxUI.LexiconGuardianAsset = RegisterLexiconAsset(lexiconPath) end
    end
    AuxUI.LexiconGuardianAsset = AuxUI.LexiconGuardianAsset or AuxUI.GuardianAsset
end

-- Living Worlds keeps every character inside the pasted build, but decodes
-- only the selected/previewed world. This avoids six PNG writes during startup.
do
    local embeddedWorlds = {
    ["Infernal Bloom"] = {file = "LRRXWARE_Infernal_Guardian_V14.png", data = [[]]},
    ["Tropical Eden"] = {file = "LRRXWARE_Tropical_Guardian_V14.png", data = [[]]},
    ["Moonlit Sanctuary"] = {file = "LRRXWARE_Moonlit_Guardian_V14.png", data = [[]]},
    ["Sakura Reverie"] = {file = "LRRXWARE_Sakura_Guardian_V14.png", data = [[]]},
    ["Frostglass Palace"] = {file = "LRRXWARE_Frostglass_Guardian_V14.png", data = [[]]},
    ["Ocean Reverie"] = {file = "LRRXWARE_Ocean_Guardian_V14.png", data = [[]]}
    }
    AuxUI.WorldStyleOrder = {
        "Heavenly Garden", "Infernal Bloom", "Tropical Eden", "Moonlit Sanctuary",
        "Sakura Reverie", "Frostglass Palace", "Ocean Reverie", "Starlit Library"
    }
    AuxUI.WorldAssets = {
        ["Heavenly Garden"] = AuxUI.GuardianAsset,
        ["Starlit Library"] = AuxUI.LexiconGuardianAsset
    }

    local assetGetter = GetExecutorGlobal("getcustomasset") or GetExecutorGlobal("getsynasset") or GetExecutorGlobal("getasset")
    local function DecodeWorldBase64(data)
        local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local lookup, output, segment = {}, {}, {}
        for index = 1, #alphabet do lookup[string.byte(alphabet, index)] = index - 1 end
        for index = 1, #data, 4 do
            local aByte, bByte = string.byte(data, index), string.byte(data, index + 1)
            local cByte, dByte = string.byte(data, index + 2), string.byte(data, index + 3)
            local cPadding, dPadding = cByte == nil or cByte == 61, dByte == nil or dByte == 61
            local packed = (lookup[aByte] or 0) * 262144 + (lookup[bByte] or 0) * 4096
                + (cPadding and 0 or (lookup[cByte] or 0)) * 64
                + (dPadding and 0 or (lookup[dByte] or 0))
            segment[#segment + 1] = string.char(math.floor(packed / 65536) % 256)
            if not cPadding then segment[#segment + 1] = string.char(math.floor(packed / 256) % 256) end
            if not dPadding then segment[#segment + 1] = string.char(packed % 256) end
            if #segment >= 2048 then output[#output + 1], segment = table.concat(segment), {} end
        end
        if #segment > 0 then output[#output + 1] = table.concat(segment) end
        return table.concat(output)
    end

    local function RegisterWorldAsset(path)
        if type(assetGetter) ~= "function" then return nil end
        if type(executorIsFile) == "function" then
            local ok, exists = pcall(executorIsFile, path)
            if not ok or not exists then return nil end
        end
        local ok, asset = pcall(assetGetter, path)
        return ok and asset and tostring(asset) or nil
    end

    AuxUI.LoadWorldAsset = function(themeName)
        themeName = tostring(themeName or Config.ThemeMode)
        if AuxUI.WorldAssets[themeName] then return AuxUI.WorldAssets[themeName] end
        local spec = embeddedWorlds[themeName]
        if not spec then return AuxUI.GuardianAsset end

        local asset = RegisterWorldAsset(spec.file)
        if not asset and spec.data and type(executorWriteFile) == "function" and type(assetGetter) == "function" then
            local ok = pcall(executorWriteFile, spec.file, DecodeWorldBase64(spec.data))
            if ok then asset = RegisterWorldAsset(spec.file) end
        end
        if asset then
            AuxUI.WorldAssets[themeName] = asset
            spec.data = nil
        end
        return asset
    end

    if tostring(Config.BootAngelAsset or "") == "" then
        AuxUI.GuardianAsset = AuxUI.LoadWorldAsset(Config.ThemeMode) or AuxUI.GuardianAsset
    end

    -- V15 action atlases use eight authored poses: four quiet/blink frames on
    -- the first row and four theme-specific action frames on the second. They
    -- stay compressed inside this one-file build and only the selected world
    -- is decoded, so switching themes is rich without making startup stutter.
    AuxUI.WorldActionSpecs = {
        ["Heavenly Garden"] = {file = "LRRXWARE_Heavenly_Actions_V15.png", width = 200, height = 200, data = [[]]},
        ["Infernal Bloom"] = {file = "LRRXWARE_Infernal_Actions_V15.png", width = 180, height = 240, data = [[]]},
        ["Tropical Eden"] = {file = "LRRXWARE_Tropical_Actions_V15.png", width = 180, height = 240, data = [[]]},
        ["Moonlit Sanctuary"] = {file = "LRRXWARE_Moonlit_Actions_V15.png", width = 180, height = 240, data = [[]]},
        ["Sakura Reverie"] = {file = "LRRXWARE_Sakura_Actions_V15.png", width = 180, height = 240, data = [[]]},
        ["Frostglass Palace"] = {file = "LRRXWARE_Frostglass_Actions_V15.png", width = 180, height = 240, data = [[]]},
        ["Ocean Reverie"] = {file = "LRRXWARE_Ocean_Actions_V15.png", width = 160, height = 240, data = [[]]},
        ["Starlit Library"] = {file = "LRRXWARE_Starlit_Actions_V15.png", width = 180, height = 240, data = [[]]}
    }
    AuxUI.WorldActionAssets = {}
    AuxUI.LoadWorldActionAsset = function(themeName)
        themeName = tostring(themeName or Config.ThemeMode)
        local loaded = AuxUI.WorldActionAssets[themeName]
        if loaded then return loaded, AuxUI.WorldActionSpecs[themeName] end
        local spec = AuxUI.WorldActionSpecs[themeName]
        if not spec then return nil, nil end
        local asset = RegisterWorldAsset(spec.file)
        if not asset and spec.data and type(executorWriteFile) == "function" and type(assetGetter) == "function" then
            local ok = pcall(executorWriteFile, spec.file, DecodeWorldBase64(spec.data))
            if ok then asset = RegisterWorldAsset(spec.file) end
        end
        if asset then
            AuxUI.WorldActionAssets[themeName] = asset
            spec.data = nil
        end
        return asset, spec
    end
    AuxUI.GuardianActionAsset, AuxUI.GuardianActionSpec = AuxUI.LoadWorldActionAsset(Config.ThemeMode)
end

-- Shared, low-cost character director. It changes atlas rectangles only while
-- an action is happening; there is no RenderStepped animation connection.
AuxUI.CharacterViews = {}
AuxUI.CharacterViewSet = {}
AuxUI.CharacterActionToken = 0
AuxUI.CharacterActionPaused = false
AuxUI.CharacterFrame = 1
AuxUI.CharacterActionName = "READY"

AuxUI.SetCharacterFrame = function(frameIndex)
    local spec = AuxUI.GuardianActionSpec
    local asset = AuxUI.GuardianActionAsset
    frameIndex = math.clamp(math.floor(tonumber(frameIndex) or 1), 1, 8)
    AuxUI.CharacterFrame = frameIndex
    for _, entry in ipairs(AuxUI.CharacterViews) do
        local view = entry.View
        if view and view.Parent then
            if asset and spec then
                view.Image = tostring(asset)
                view.ImageRectSize = Vector2.new(spec.width, spec.height)
                view.ImageRectOffset = Vector2.new(((frameIndex - 1) % 4) * spec.width, math.floor((frameIndex - 1) / 4) * spec.height)
            else
                view.Image = tostring(AuxUI.GuardianAsset or "")
                view.ImageRectSize = Vector2.new(0, 0)
                view.ImageRectOffset = Vector2.new(0, 0)
            end
        end
    end
end

AuxUI.AttachCharacterView = function(view, transparency)
    if not view then return end
    table.insert(AuxUI.CharacterViews, {View = view, Transparency = transparency or 0})
    AuxUI.CharacterViewSet[view] = true
    view.ImageTransparency = transparency or 0
    view.ScaleType = Enum.ScaleType.Fit
    AuxUI.SetCharacterFrame(AuxUI.CharacterFrame)
end

AuxUI.PlayCharacterAction = function(actionName, force)
    if Config.CharacterMotion == false or Config.ShowAngel == false or (AuxUI.CharacterActionPaused and not force) then return end
    if not AuxUI.GuardianActionAsset then return end
    if Config.CharacterActionStyle == "Gentle" and actionName ~= "blink" then actionName = "blink" end
    local sequences = {
        greet = {1, 5, 6, 7, 6, 5, 1},
        celebrate = {1, 5, 6, 7, 8, 7, 5, 1},
        cast = {1, 5, 6, 7, 8, 1},
        blink = {1, 2, 3, 2, 1}
    }
    local sequence = sequences[actionName] or sequences.blink
    AuxUI.CharacterActionToken = AuxUI.CharacterActionToken + 1
    local token = AuxUI.CharacterActionToken
    AuxUI.CharacterActionName = string.upper(actionName or "blink")
    if AuxUI.CharacterActionLabel then AuxUI.CharacterActionLabel.Text = AuxUI.CharacterActionName end
    task.spawn(function()
        for _, frameIndex in ipairs(sequence) do
            if token ~= AuxUI.CharacterActionToken or (AuxUI.CharacterActionPaused and not force) or Config.CharacterMotion == false then return end
            AuxUI.SetCharacterFrame(frameIndex)
            task.wait(actionName == "blink" and 0.12 or 0.145)
        end
        if token == AuxUI.CharacterActionToken then
            AuxUI.CharacterActionName = "READY"
            if AuxUI.CharacterActionLabel then AuxUI.CharacterActionLabel.Text = "READY" end
        end
    end)
end

AuxUI.RefreshCharacterActionAsset = function(themeName)
    local asset, spec = AuxUI.LoadWorldActionAsset and AuxUI.LoadWorldActionAsset(themeName)
    AuxUI.GuardianActionAsset, AuxUI.GuardianActionSpec = asset, spec
    AuxUI.CharacterActionToken = AuxUI.CharacterActionToken + 1
    AuxUI.SetCharacterFrame(1)
    if asset then task.defer(function() AuxUI.PlayCharacterAction("greet") end) end
    return asset ~= nil
end

