        local wordPart, timePart = message:match("Word:%s*(%S+)%s+Time to respond:%s*(%d+)")
        if wordPart and timePart then
            isMyTurnLogDetected = true
            logRequiredLetters = AuxUI.NormalizeWordText(wordPart)
            turnExpiryTime = tick() + tonumber(timePart)
        end
    end)
end)

local Words = {}
