-- Startup dictionary policy: fetch a cache-busted source, never replace a
-- larger valid cache with a smaller response, and merge older/local sources
-- instead of silently throwing their unique words away.
local fetchedWordBody = nil
local cachedWordBody = nil
local function ReadWordFile(name)
    if type(executorIsFile) ~= "function" or type(executorReadFile) ~= "function" then return nil end
    local existsOk, exists = pcall(executorIsFile, name)
    if not existsOk or not exists then return nil end
    local readOk, body = pcall(executorReadFile, name)
    if readOk and type(body) == "string" and #body > 0 then return body end
    return nil
end

local function FetchWords()
    UpdateStatus("gathering the complete public dictionary...", THEME.Warning)
    cachedWordBody = ReadWordFile(fileName) or ReadWordFile(legacyFileName)
    local success, res = pcall(function()
        if type(request) == "function" then
            return request({Url = url, Method = "GET", Headers = {["Cache-Control"] = "no-cache"}})
        end
        return {Body = game:HttpGet(url)}
    end)

    local body = nil
    if success and type(res) == "string" then
        body = res
    elseif success and type(res) == "table" then
        body = res.Body or res.body
    end
    if (not body or #body < 100000 or not body:find("\n", 1, true)) and type(game.HttpGet) == "function" then
        local fallbackOk, fallbackBody = pcall(function() return game:HttpGet(url) end)
        if fallbackOk then body = fallbackBody end
    end

    if type(body) == "string" and #body >= 100000 and body:find("\n", 1, true) and not body:lower():find("<!doctype", 1, true) then
        fetchedWordBody = body
        if type(executorWriteFile) == "function" and (not cachedWordBody or #body >= #cachedWordBody) then
            pcall(executorWriteFile, fileName, body)
        end
        UpdateStatus("fresh dictionary received", THEME.Success)
    else
        UpdateStatus(cachedWordBody and "using the larger saved dictionary" or "dictionary source unavailable", cachedWordBody and THEME.Warning or THEME.Danger)
    end
    task.wait(0.16)
end

FetchWords()

local function LoadList()
    UpdateStatus("indexing every available word...", THEME.Warning)
    local parsedAny = false
    local function MergeBody(content)
        if type(content) ~= "string" or #content == 0 then return end
        parsedAny = true
        local scanned = 0
        for w in content:gmatch("[^\r\n]+") do
            local clean = AuxUI.NormalizeWordText(w)
            if #clean > 0 and clean:match("^[a-z'%-]+$") and not SeenWords[clean] then
                SeenWords[clean] = true
                table.insert(Words, clean)
                AdjustPrefixLiveCounts(clean, 1)
            end
            scanned = scanned + 1
            if scanned % 12000 == 0 then
                LoadingStatus.Text = "indexing words  ·  " .. tostring(#Words) .. " ready"
                RunService.Heartbeat:Wait()
            end
        end
    end

    MergeBody(fetchedWordBody)
    if cachedWordBody and cachedWordBody ~= fetchedWordBody then MergeBody(cachedWordBody) end
    local legacyBody = ReadWordFile(legacyFileName)
    if legacyBody and legacyBody ~= fetchedWordBody and legacyBody ~= cachedWordBody then MergeBody(legacyBody) end

    -- Optional personal/mirror sources are merged, never substituted for the
    -- trusted public list. A bad endpoint is ignored without breaking startup.
    if type(Config.ExtraDictionaryUrls) == "table" then
        for sourceIndex, extraUrl in ipairs(Config.ExtraDictionaryUrls) do
            if sourceIndex > 3 then break end
            if type(extraUrl) == "string" and extraUrl:match("^https://") then
                LoadingStatus.Text = "merging dictionary source " .. tostring(sourceIndex + 1)
                local extraOk, extraBody = pcall(function() return game:HttpGet(extraUrl) end)
                if extraOk and type(extraBody) == "string" and #extraBody > 0 and not extraBody:lower():find("<!doctype", 1, true) then
                    MergeBody(extraBody)
                end
            end
        end
    end

    if parsedAny then
        local prettyCount = tostring(#Words):reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "")
        UpdateStatus(prettyCount .. " verified words are ready", THEME.Success)
    else
        UpdateStatus("no word collection was found", THEME.Danger)
    end
    task.wait(0.22)
end

LoadList()
