                Position = UDim2.new(0.5, 0, 0.5, -18),
                BackgroundTransparency = 1,
                GroupTransparency = 1
            }):Play()
            TweenService:Create(BootBackdrop, TweenInfo.new(0.72, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
                BackgroundTransparency = 1
            }):Play()
            TweenService:Create(BootScale, TweenInfo.new(0.62, Enum.EasingStyle.Quint, Enum.EasingDirection.In), {
                Scale = BootScale.Scale * 0.965
            }):Play()

            for _, object in ipairs(BootBackdrop:GetChildren()) do
                if object:IsA("Frame") and object ~= BootCard then
                    TweenService:Create(object, TweenInfo.new(0.66), {BackgroundTransparency = 1}):Play()
                end
            end

            for _, object in ipairs(BootCard:GetDescendants()) do
                if object:IsA("TextLabel") or object:IsA("TextButton") then
                    TweenService:Create(object, TweenInfo.new(0.46), {TextTransparency = 1, BackgroundTransparency = 1}):Play()
                elseif object:IsA("ImageLabel") or object:IsA("ImageButton") then
                    TweenService:Create(object, TweenInfo.new(0.58, Enum.EasingStyle.Sine), {ImageTransparency = 1, BackgroundTransparency = 1}):Play()
                elseif object:IsA("Frame") then
                    TweenService:Create(object, TweenInfo.new(0.46), {BackgroundTransparency = 1}):Play()
                elseif object:IsA("UIStroke") then
                    TweenService:Create(object, TweenInfo.new(0.46), {Transparency = 1}):Play()
                end
            end
            task.wait(0.74)
        end

        if LoadingGui and LoadingGui.Parent then LoadingGui:Destroy() end
        FinishBootTransition = nil
    end
end
