table.sort(Words)
Buckets = {}
for _, w in ipairs(Words) do
    local c = w:sub(1,1) or ""
    if c == "" then c = "#" end
    Buckets[c] = Buckets[c] or {}
    table.insert(Buckets[c], w)
end

if Config.CustomWords then
    for _, w in ipairs(Config.CustomWords) do
        local clean = AuxUI.NormalizeWordText(w)
        if #clean > 0 and not SeenWords[clean] then
            SeenWords[clean] = true
            table.insert(Words, clean)
            AdjustPrefixLiveCounts(clean, 1)
            local c = clean:sub(1,1) or ""
            if c == "" then c = "#" end
            Buckets[c] = Buckets[c] or {}
            table.insert(Buckets[c], clean)
        end
    end
end

-- Custom entries are merged into the same sorted buckets used by binary search.
for _, bucketWords in pairs(Buckets) do table.sort(bucketWords) end

-- Dedicated punctuation indexes are tiny compared with the full dictionary.
-- They make '-' and apostrophe prompts complete without ever rescanning every
-- ordinary word on the frame where a competitive turn begins.
AuxUI.PunctuationBuckets = {Hyphen = {}, Apostrophe = {}}
AuxUI.RebuildPunctuationIndexes = function()
    table.clear(AuxUI.PunctuationBuckets.Hyphen)
    table.clear(AuxUI.PunctuationBuckets.Apostrophe)
    for _, word in ipairs(Words) do
        if word:find("-", 1, true) then
            AuxUI.PunctuationBuckets.Hyphen[#AuxUI.PunctuationBuckets.Hyphen + 1] = word
        end
        if word:find("'", 1, true) then
            AuxUI.PunctuationBuckets.Apostrophe[#AuxUI.PunctuationBuckets.Apostrophe + 1] = word
        end
    end
    table.sort(AuxUI.PunctuationBuckets.Hyphen)
    table.sort(AuxUI.PunctuationBuckets.Apostrophe)
end
AuxUI.RebuildPunctuationIndexes()

-- Clear memory
SeenWords = nil

-- Mark completed words unavailable in O(1). The sorted dictionary stays intact,
-- so a submission never shifts hundreds of thousands of table entries.
local function RemoveRuntimeWord(rawWord)
    local clean = AuxUI.NormalizeWordText(rawWord)
    if clean == "" then return false end
    if UsedWords[clean] then return false end

    if not Blacklist[clean] then AdjustPrefixLiveCounts(clean, -1) end
    UsedWords[clean] = true

    RandomPriority[clean] = nil

    for button, data in pairs(ButtonData) do
        if data and data.word == clean then
            button.Visible = false
            ButtonData[button] = nil
        end
    end

    -- A completed word means the prompt is leaving this player. Cancel stale
    -- side work, but keep the painted rows until the next real own-turn prompt
    -- arrives; rebuilding here was the largest handoff hitch.
    sideScanGeneration = sideScanGeneration + 1
    trapScanPending = false
    listUpdatePending = false
    currentBestMatch = nil
    return true
end

local function BlacklistRuntimeWord(rawWord)
    local clean = AuxUI.NormalizeWordText(rawWord)
    if clean == "" then return false end
    if Blacklist[clean] then return false end
    if not UsedWords[clean] then AdjustPrefixLiveCounts(clean, -1) end
    Blacklist[clean] = true
    RandomPriority[clean] = nil
    forceUpdateList = true
    return true
end

-- A transport/input miss is not the same as the server rejecting a valid
-- word. Put the word back when the typed tiles drifted, so one lost key does
-- not silently remove a usable solve for the rest of the session.
AuxUI.RestoreRuntimeWord = function(rawWord)
    local clean = AuxUI.NormalizeWordText(rawWord)
    if clean == "" or not UsedWords[clean] then return false end
    UsedWords[clean] = nil
    if not Blacklist[clean] then AdjustPrefixLiveCounts(clean, 1) end
    forceUpdateList = true
    return true
end

local function shuffleTable(t)
    local n = #t
    for i = n, 2, -1 do
        local j = math.random(i)
        t[i], t[j] = t[j], t[i]
    end
    return t
end

local HardLetterScores = {
    x = 10, z = 9, q = 9, j = 8, v = 6, k = 5, b = 4, f = 3, w = 3,
    y = 2, g = 2, p = 2
}

local function GetKillerScore(word)
    local lastChar = word:sub(-1)
    return HardLetterScores[lastChar] or 0
end

-- The old comparison sorts could perform hundreds of thousands of callbacks
-- on common one-letter prompts. These stable bucket passes preserve the same
-- length/Killer priorities in linear time.
local function SortByLengthFast(list, descending)
    if #list < 2 then return list end
    local lengths = {}
    local minLength = math.huge
    local maxLength = 0
    for _, word in ipairs(list) do
        local length = #word
        local group = lengths[length]
        if not group then
            group = {}
            lengths[length] = group
        end
        group[#group + 1] = word
        if length < minLength then minLength = length end
        if length > maxLength then maxLength = length end
    end

    local writeIndex = 1
    local function WriteLength(length)
        local group = lengths[length]
        if group then
            for _, word in ipairs(group) do
                list[writeIndex] = word
                writeIndex = writeIndex + 1
            end
        end
    end

    if descending then
        for length = maxLength, minLength, -1 do WriteLength(length) end
    else
        for length = minLength, maxLength do WriteLength(length) end
    end
    return list
end

local function SortKillerFast(list)
    if #list < 2 then return list end
    local scoreGroups = {}
    for _, word in ipairs(list) do
        local score = GetKillerScore(word)
        local group = scoreGroups[score]
        if not group then
            group = {}
            scoreGroups[score] = group
        end
        group[#group + 1] = word
    end

    local writeIndex = 1
    for _, score in ipairs({10, 9, 8, 6, 5, 4, 3, 2, 0}) do
        local group = scoreGroups[score]
        if group then
            SortByLengthFast(group, false)
            for _, word in ipairs(group) do
                list[writeIndex] = word
                writeIndex = writeIndex + 1
            end
        end
    end
    return list
end

-- Punctuation stays out of every normal order. It is allowed only when the
-- live/search prompt asks for it, or when its dedicated order is selected.
local function PassesPunctuationFilter(word, prompt)
    prompt = AuxUI.NormalizeWordText(prompt)
    local hasHyphen = word:find("-", 1, true) ~= nil
    local hasApostrophe = word:find("'", 1, true) ~= nil or word:find("’", 1, true) ~= nil

    if sortMode == "Hyphen" then return hasHyphen end
    if sortMode == "Apostrophe" then return hasApostrophe end
    if hasHyphen and not prompt:find("-", 1, true) then return false end
    if hasApostrophe and not prompt:find("'", 1, true) then return false end
    return true
end

local function getDistance(s1, s2)
    if #s1 == 0 then
        return #s2
    end
    if #s2 == 0 then
        return #s1
    end
    if s1 == s2 then
        return 0
    end
    local matrix = {}
    for i = 0, #s1 do matrix[i] = {[0] = i} end
    for j = 0, #s2 do matrix[0][j] = j end
    for i = 1, #s1 do
        for j = 1, #s2 do
            local cost = (s1:sub(i,i) == s2:sub(j,j)) and 0 or 1
            matrix[i][j] = math.min(matrix[i-1][j]+1, matrix[i][j-1]+1, matrix[i-1][j-1]+cost)
        end
    end
    return matrix[#s1][#s2]
end

local function Tween(obj, props, time)
    TweenService:Create(obj, TweenInfo.new(time or 0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), props):Play()
end

local function GetCurrentGameWord(providedFrame)
    local frame = providedFrame
    if not frame then
        local player = Players.LocalPlayer
        local gui = player and player:FindFirstChild("PlayerGui")
        local inGame = gui and gui:FindFirstChild("InGame")
        frame = inGame and inGame:FindFirstChild("Frame")
    end

    local container = frame and frame:FindFirstChild("CurrentWord")
    if not container then return "", false end
    
    local detected = ""
    local censored = false
    
    local children = container:GetChildren()
    local letterData = {}
    
    for _, c in ipairs(children) do
        if c:IsA("GuiObject") and c.Visible then
            local txt = c:FindFirstChild("Letter")
            if txt and txt:IsA("TextLabel") and txt.TextTransparency < 1 then
                table.insert(letterData, {
                    Obj = c,
                    Txt = txt,
                    X = c.AbsolutePosition.X,
                    Id = tonumber(c.Name) or 0
                })
            end
        end
    end
    
    table.sort(letterData, function(a,b)
        if math.abs(a.X - b.X) > 2 then
            return a.X < b.X
        end
        return a.Id < b.Id
    end)

    for _, data in ipairs(letterData) do
        local t = tostring(data.Txt.Text)
        if t:find("#") or t:find("%*") then censored = true end
        detected = detected .. t
    end
    
    return AuxUI.NormalizeWordText(detected), censored
end

local function GetTurnInfo(providedFrame)
    if isMyTurnLogDetected then
        if tick() < turnExpiryTime then
            return true, logRequiredLetters
        else
            isMyTurnLogDetected = false
        end
    end

    local frame = providedFrame
    if not frame then
        local player = Players.LocalPlayer
        local gui = player and player:FindFirstChild("PlayerGui")
        local inGame = gui and gui:FindFirstChild("InGame")
        frame = inGame and inGame:FindFirstChild("Frame")
    end

    local typeLbl = frame and frame:FindFirstChild("Type")
    
    if typeLbl and typeLbl:IsA("TextLabel") then
        local text = typeLbl.Text
        local player = Players.LocalPlayer
        if text:sub(1, #player.Name) == player.Name or text:sub(1, #player.DisplayName) == player.DisplayName then
            local prompt = text:match("starting with:%s*(%S+)")
            if prompt then prompt = AuxUI.NormalizeWordText(prompt) end
            return true, prompt
        end
    end
    return false, nil
end

