local MainScale = Instance.new("UIScale", MainFrame)
local viewportConn
local function UpdateResponsiveScale()
    local camera = workspace.CurrentCamera
    local viewport = camera and camera.ViewportSize or Vector2.new(1280, 720)
    local widthScale = (viewport.X - 20) / MAIN_WIDTH
    local heightScale = (viewport.Y - 28) / MAIN_HEIGHT
    local target = math.min(1, widthScale, heightScale)
    if UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then
        target = math.min(target, 0.94)
    end
    MainScale.Scale = math.clamp(target, 0.55, 1)
    if AuxUI and AuxUI.Responsive then AuxUI.Responsive(viewport) end
end
UpdateResponsiveScale()
if workspace.CurrentCamera then
    viewportConn = workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(UpdateResponsiveScale)
end

local function EnableDragging(frame, handle)
    local dragHandle = handle or frame
    local dragging, dragInput, dragStart, startPos
    local function Update(input)
        local delta = input.Position - dragStart
        frame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
    end
    
    dragHandle.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            dragStart = input.Position
            startPos = frame.Position
            
            input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then
                    dragging = false
                end
            end)
        end
    end)
    
    dragHandle.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
            dragInput = input
        end
    end)
    
    UserInputService.InputChanged:Connect(function(input)
        if input == dragInput and dragging then
            Update(input)
        end
    end)
end

