    button.Font = Enum.Font.GothamBold
    button.TextSize = 9
    button.AutoButtonColor = false
    button.ZIndex = 9
    Instance.new("UICorner", button).CornerRadius = UDim.new(0, 11)
    local marker = Instance.new("Frame", button)
    marker.Name = "ActiveMarker"
    marker.AnchorPoint = Vector2.new(0.5, 1)
