    marker.Position = UDim2.new(0.5, 0, 1, -2)
    marker.BackgroundColor3 = THEME.Accent
    marker.BackgroundTransparency = 1
    marker.BorderSizePixel = 0
    Instance.new("UICorner", marker).CornerRadius = UDim.new(1, 0)
    return button
end

