local function StyleModeButton(button, active, color)
    TweenService:Create(button, TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
        BackgroundTransparency = active and 0.04 or 1,
        BackgroundColor3 = active and (color or THEME.Lavender) or THEME.Surface,
        TextColor3 = active and THEME.Text or THEME.SubText
    }):Play()
    local marker = button:FindFirstChild("ActiveMarker")
    if marker then
        marker.BackgroundColor3 = color or THEME.Accent
        TweenService:Create(marker, TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
            BackgroundTransparency = active and 0 or 1,
            Size = UDim2.fromOffset(active and 32 or 16, 3)
        }):Play()
    end
end

AuxUI.SyncModeRail = function()
    StyleModeButton(WordsModeButton, not trapMode and not Config.SpamMode and not AuxUI.WorldOpen and not AuxUI.LexiconOpen, THEME.Lavender)
