    StyleModeButton(SpamModeButton, Config.SpamMode == true, THEME.Lavender)
    StyleModeButton(AuxUI.LexiconModeButton, AuxUI.LexiconOpen == true, THEME.Gold)
    StyleModeButton(WorldModeButton, AuxUI.WorldOpen == true, THEME.Sage)
end

