-- Authored pose actions replace the old floating tween. On a live turn the
-- director freezes on frame one, leaving the solver's entire frame budget to
-- prompt parsing, Trap, Endings, and typing.
do
    AuxUI.CharacterMotionState = false
    AuxUI.SetGuardianMotionActive = function(active)
        local shouldMove = active == true and Config.CharacterMotion ~= false and Config.ShowAngel == true
        if AuxUI.CharacterMotionState == shouldMove then return end
        AuxUI.CharacterMotionState = shouldMove
        AuxUI.CharacterActionPaused = not shouldMove
        AuxUI.CharacterActionToken = AuxUI.CharacterActionToken + 1
        if shouldMove then
            task.defer(function() AuxUI.PlayCharacterAction("blink") end)
        else
            AuxUI.SetCharacterFrame(1)
            AuxUI.CharacterActionName = "FOCUS"
            if AuxUI.CharacterActionLabel then AuxUI.CharacterActionLabel.Text = "FOCUS" end
        end
    end

    AuxUI.RefreshGuardianAsset = function(themeName)
        local asset = AuxUI.LoadWorldAsset and AuxUI.LoadWorldAsset(themeName) or AuxUI.GuardianAsset
        if asset then AuxUI.GuardianAsset = asset end
        local actionReady = AuxUI.RefreshCharacterActionAsset and AuxUI.RefreshCharacterActionAsset(themeName)
        if not asset and not actionReady then return false end
        for _, view in ipairs(AuxUI.GuardianViews or {}) do
            if view and view.Parent and view.Name ~= "LexiconGuardian" then
                if not actionReady or not AuxUI.CharacterViewSet[view] then
                    view.Image = tostring(asset or AuxUI.GuardianAsset or "")
                    view.ImageRectSize = Vector2.new(0, 0)
                    view.ImageRectOffset = Vector2.new(0, 0)
                end
                view.Visible = Config.ShowAngel == true
            end
        end
        HeaderLetter.Visible = not (Config.ShowAngel and (actionReady or asset))
        GuardianMini.ImageTransparency = 1
        TweenService:Create(GuardianMini, TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
            ImageTransparency = Config.ShowAngel and 0 or 1
        }):Play()
        return actionReady or asset ~= nil
    end
end

