        if not unloaded and ScreenGui and ScreenGui.Enabled and Config.CharacterMotion ~= false
            and Config.ShowAngel and not AuxUI.CharacterActionPaused then
            AuxUI.PlayCharacterAction("blink")
        end
    end
end)

