local function CreateToggle(text, pos, callback)
    local btn = Instance.new("TextButton", TogglesFrame)
    btn.Text = text
    btn.Font = Enum.Font.GothamMedium
    btn.TextSize = 10
    btn.TextColor3 = THEME.Success
    btn.TextXAlignment = Enum.TextXAlignment.Left
    btn.BackgroundColor3 = THEME.Surface2
    btn.BackgroundTransparency = 0.14
    local secondColumn = pos.X.Offset >= 100
    btn.Size = UDim2.new(0.5, -21, 0, 34)
    btn.Position = UDim2.new(secondColumn and 0.5 or 0, secondColumn and 7 or 14, pos.Y.Scale, pos.Y.Offset)
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 12)
    local outline = Instance.new("UIStroke", btn)
    outline.Color = THEME.Border
    outline.Transparency = 0.44
    local padding = Instance.new("UIPadding", btn)
    padding.PaddingLeft = UDim.new(0, 19)
    padding.PaddingRight = UDim.new(0, 8)
    local stateRail = Instance.new("Frame", btn)
    stateRail.Name = "StateRail"
    stateRail.Size = UDim2.fromOffset(4, 18)
    stateRail.Position = UDim2.new(0, 8, 0.5, -9)
    stateRail.BackgroundColor3 = THEME.Accent
    stateRail.BackgroundTransparency = 0.18
    stateRail.BorderSizePixel = 0
    Instance.new("UICorner", stateRail).CornerRadius = UDim.new(1, 0)
    
    btn.MouseButton1Click:Connect(function()
        local newState, newText, newColor = callback()
        btn.Text = newText
        btn.TextColor3 = newColor
        stateRail.BackgroundColor3 = newColor or THEME.Accent
        stateRail.BackgroundTransparency = newState and 0 or 0.62
        SaveConfig()
    end)
    return btn
end

