ThemeBtn.TextColor3 = THEME.Accent
ThemeBtn.Size = UDim2.new(1, -28, 0, 34)
do
    local function DecorateThemeChoice()
        ThemeBtn.TextXAlignment = Enum.TextXAlignment.Left
        local themePadding = Instance.new("UIPadding", ThemeBtn)
        themePadding.PaddingLeft = UDim.new(0, 38)
        local themeSwatch = Instance.new("Frame", ThemeBtn)
        themeSwatch.Size = UDim2.fromOffset(20,20)
        themeSwatch.Position = UDim2.new(0,10,0.5,-10)
        themeSwatch.BackgroundColor3 = THEME.Accent
        themeSwatch.BorderSizePixel = 0
        Instance.new("UICorner",themeSwatch).CornerRadius = UDim.new(1,0)
        local swatchStroke = Instance.new("UIStroke",themeSwatch)
        swatchStroke.Color = THEME.Gold
        swatchStroke.Transparency = 0.35
        AuxUI.WorldDots = {}
        for i, world in ipairs({
            {"Heavenly Garden",Color3.fromRGB(142,121,190)},
            {"Infernal Bloom",Color3.fromRGB(226,89,91)},
            {"Tropical Eden",Color3.fromRGB(34,151,139)},
            {"Moonlit Sanctuary",Color3.fromRGB(108,192,221)},
            {"Sakura Reverie",Color3.fromRGB(202,116,156)},
            {"Frostglass Palace",Color3.fromRGB(108,145,205)},
            {"Ocean Reverie",Color3.fromRGB(54,157,174)},
            {"Starlit Library",Color3.fromRGB(132,102,183)}
        }) do
            local dotSize = world[1] == Config.ThemeMode and 10 or 7
            local worldDot = Instance.new("Frame",ThemeBtn)
            worldDot.Size = UDim2.fromOffset(dotSize,dotSize)
            worldDot.Position = UDim2.new(1,-(12 + ((8-i)*14)),0.5,-math.floor(dotSize/2))
            worldDot.BackgroundColor3 = world[2]
            worldDot.BorderSizePixel = 0
            worldDot.Name = world[1]
            Instance.new("UICorner",worldDot).CornerRadius = UDim.new(1,0)
            AuxUI.WorldDots[#AuxUI.WorldDots + 1] = worldDot
        end
        AuxUI.SyncWorldDots = function()
            for index, dot in ipairs(AuxUI.WorldDots) do
                local selected = dot.Name == Config.ThemeMode
                local dotSize = selected and 10 or 7
                dot.Size = UDim2.fromOffset(dotSize, dotSize)
                dot.Position = UDim2.new(1, -(12 + ((8-index)*14)), 0.5, -math.floor(dotSize/2))
            end
        end
    end
    DecorateThemeChoice()
end

