-- Celestial Lexicon: a completely independent, cached web reader. All HTTP
-- work runs off the render callback, stale searches cannot repaint the panel,
-- and network failure never interrupts the solver.
(function()
    local LexiconCache = {}
    local lexiconRequestToken = 0

    local function UrlEncode(value)
        local ok, encoded = pcall(function() return HttpService:UrlEncode(tostring(value or "")) end)
        if ok and encoded then return encoded end
        return tostring(value or ""):gsub("([^%w%-_%.~])", function(char)
            return string.format("%%%02X", string.byte(char))
        end)
    end

    local function HttpGetText(url)
        if type(request) == "function" then
            local ok, response = pcall(request, {
                Url = url,
                Method = "GET",
                Headers = { ["User-Agent"] = "LRRXWARE-Living-Worlds/14" }
            })
            if ok and type(response) == "table" then
                local status = tonumber(response.StatusCode or response.Status or 200) or 0
                local body = response.Body or response.body
                if status >= 200 and status < 300 and type(body) == "string" then return body end
            elseif ok and type(response) == "string" then
                return response
            end
        end

        local ok, body = pcall(function() return game:HttpGet(url, true) end)
        if ok and type(body) == "string" then return body end
        return nil
    end

    local function DecodeJson(body)
        if type(body) ~= "string" or body == "" then return nil end
        local ok, decoded = pcall(function() return HttpService:JSONDecode(body) end)
        return ok and decoded or nil
    end

    local function LocalVaultContains(word)
        local bucket = Buckets and Buckets[word:sub(1, 1)]
        if not bucket then return false end
        local left, right = 1, #bucket
        while left <= right do
            local middle = math.floor((left + right) / 2)
            local current = bucket[middle]
            if current == word then return true end
            if current < word then left = middle + 1 else right = middle - 1 end
        end
        return false
    end

    local function ParseDictionary(data)
        if type(data) ~= "table" or type(data[1]) ~= "table" then return nil, nil end
        local entry = data[1]
        local phonetic = tostring(entry.phonetic or "")
        if phonetic == "" and type(entry.phonetics) == "table" then
            for _, item in ipairs(entry.phonetics) do
                if type(item) == "table" and type(item.text) == "string" and item.text ~= "" then
                    phonetic = item.text
                    break
                end
            end
        end

        local lines, count = {}, 0
        for _, meaning in ipairs(type(entry.meanings) == "table" and entry.meanings or {}) do
            local part = tostring(meaning.partOfSpeech or "meaning")
            local definitions = type(meaning.definitions) == "table" and meaning.definitions or {}
            local wroteHeading = false
            for _, definition in ipairs(definitions) do
                if type(definition) == "table" and type(definition.definition) == "string" and definition.definition ~= "" then
                    if not wroteHeading then
                        lines[#lines + 1] = string.upper(part)
                        wroteHeading = true
                    end
                    count = count + 1
                    lines[#lines + 1] = tostring(count) .. ". " .. definition.definition
                    if type(definition.example) == "string" and definition.example ~= "" then
                        lines[#lines + 1] = "   example: " .. definition.example
                    end
                    if count >= 8 then break end
                end
            end
            if count >= 8 then break end
        end
        return #lines > 0 and table.concat(lines, "\n") or nil, phonetic
    end

    local function ParseWikipedia(openData, extractData)
        local title, description, sourceUrl = nil, nil, nil
        if type(openData) == "table" then
            if type(openData[2]) == "table" then title = openData[2][1] end
            if type(openData[3]) == "table" then description = openData[3][1] end
            if type(openData[4]) == "table" then sourceUrl = openData[4][1] end
        end

        local extract = nil
        if type(extractData) == "table" and type(extractData.query) == "table" and type(extractData.query.pages) == "table" then
            for _, page in pairs(extractData.query.pages) do
                if type(page) == "table" and type(page.extract) == "string" and page.extract ~= "" then
                    extract = page.extract
                    title = page.title or title
                    break
                end
            end
        end
        local summary = extract or description
        if type(summary) == "string" and #summary > 1800 then summary = summary:sub(1, 1800) .. "..." end
        return title, summary, sourceUrl
    end

    local panel = {}
    panel.Frame = Instance.new("CanvasGroup", ScreenGui)
    panel.Frame.Name = "CelestialLexicon"
    panel.Frame.AnchorPoint = Vector2.new(0, 0.5)
    panel.Frame.Size = UDim2.fromOffset(470, MAIN_HEIGHT)
    panel.Frame.Position = UDim2.new(0, 18, 0.5, 0)
    panel.Frame.BackgroundColor3 = THEME.Background
    panel.Frame.BackgroundTransparency = 0.015
    panel.Frame.GroupTransparency = 1
    panel.Frame.BorderSizePixel = 0
    panel.Frame.Active = true
    panel.Frame.ClipsDescendants = true
    panel.Frame.Visible = false
    panel.Scale = Instance.new("UIScale", panel.Frame)
    Instance.new("UICorner", panel.Frame).CornerRadius = UDim.new(0, 30)
    local panelStroke = Instance.new("UIStroke", panel.Frame)
    panelStroke.Color = THEME.Gold
    panelStroke.Transparency = 0.18
    panelStroke.Thickness = 1.5
    local panelWash = Instance.new("UIGradient", panel.Frame)
    panelWash.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, THEME.Surface),
        ColorSequenceKeypoint.new(0.52, THEME.ItemBG),
        ColorSequenceKeypoint.new(1, THEME.Sage)
    })
    panelWash.Rotation = 128

    local topRail = Instance.new("Frame", panel.Frame)
    topRail.Size = UDim2.fromOffset(92, 4)
    topRail.Position = UDim2.new(0.5, -46, 0, 0)
    topRail.BackgroundColor3 = THEME.Gold
    topRail.BorderSizePixel = 0
    topRail.ZIndex = 8
    Instance.new("UICorner", topRail).CornerRadius = UDim.new(1, 0)

    panel.Header = Instance.new("Frame", panel.Frame)
    panel.Header.Size = UDim2.new(1, 0, 0, 92)
    panel.Header.BackgroundColor3 = THEME.Surface
    panel.Header.BackgroundTransparency = 0.24
    panel.Header.BorderSizePixel = 0
    local headerLine = Instance.new("Frame", panel.Header)
    headerLine.Size = UDim2.new(1, 0, 0, 1)
    headerLine.Position = UDim2.new(0, 0, 1, -1)
    headerLine.BackgroundColor3 = THEME.Border
    headerLine.BackgroundTransparency = 0.35
