    resultStroke.Color = THEME.Border
    resultStroke.Transparency = 0.52

    panel.Body = Instance.new("TextLabel", panel.Scroll)
    panel.Body.Size = UDim2.new(1, -30, 0, 320)
    panel.Body.Position = UDim2.fromOffset(15, 14)
    panel.Body.BackgroundTransparency = 1
    panel.Body.Text = "The lexicon stays separate from your solves.\n\nIt never types, submits, or changes your current word."
    panel.Body.TextColor3 = THEME.Text
    panel.Body.Font = AuxUI.GetFontProfile().Body
    panel.Body.TextSize = 12
    panel.Body.TextWrapped = true
    panel.Body.TextXAlignment = Enum.TextXAlignment.Left
    panel.Body.TextYAlignment = Enum.TextYAlignment.Top

    local function SetLexiconBody(text)
        panel.Body.Text = tostring(text or "")
        local lineEstimate = math.max(16, math.ceil(#panel.Body.Text / 54) + select(2, panel.Body.Text:gsub("\n", "\n")))
        local height = math.max(320, lineEstimate * 19 + 28)
        panel.Body.Size = UDim2.new(1, -30, 0, height)
        panel.Scroll.CanvasSize = UDim2.new(0, 0, 0, height + 24)
        panel.Scroll.CanvasPosition = Vector2.new(0, 0)
    end

    local function AnimateGuardian(reading)
        if not panel.Guardian.Visible then return end
        local rest = UDim2.new(1, -16, 0, 172)
        panel.Guardian.Position = UDim2.new(1, -12, 0, reading and 184 or 178)
        panel.Guardian.ImageTransparency = reading and 0.28 or 0.16
        panel.Guardian.Rotation = reading and 2 or -2
        TweenService:Create(panel.Guardian, TweenInfo.new(0.48, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
            Position = rest,
            ImageTransparency = 0.07,
            Rotation = 0
        }):Play()
        panel.GuardianAura.BackgroundTransparency = reading and 0.72 or 0.82
        TweenService:Create(panel.GuardianAura, TweenInfo.new(0.64, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
            BackgroundTransparency = 0.9
        }):Play()
    end

    local function RenderLexiconResult(word, result, fromCache)
        panel.Word.Text = word
        panel.Phonetic.Text = (result.phonetic ~= "" and result.phonetic or "pronunciation unavailable")
            .. (fromCache and "  ·  instant cache" or "  ·  web scan complete")
        local sections = {}
        sections[#sections + 1] = "DICTIONARY\n" .. (result.dictionary or "No dictionary definition was returned.")
        if result.wikipedia then
            sections[#sections + 1] = "ENCYCLOPEDIA  /  " .. tostring(result.wikiTitle or word) .. "\n" .. result.wikipedia
        else
            sections[#sections + 1] = "ENCYCLOPEDIA\nNo matching encyclopedia introduction was returned."
        end
        sections[#sections + 1] = "LOCAL LRRXWARE VAULT\n" .. (result.localWord and "This spelling exists in the loaded word vault." or "This spelling is not in the current local vault.")
        if result.sourceUrl then sections[#sections + 1] = "SOURCE\n" .. result.sourceUrl end
        SetLexiconBody(table.concat(sections, "\n\n"))
        panel.Source.Text = fromCache and "INSTANT CACHE  /  DICTIONARY + ENCYCLOPEDIA" or "WEB SCAN COMPLETE  /  DICTIONARY + ENCYCLOPEDIA"
        panel.Source.TextColor3 = THEME.Success
        panel.Search.Text = "READ"
        AnimateGuardian(false)
    end

    local function LookupWord()
        local word = tostring(panel.Input.Text or ""):lower():gsub("’", "'"):gsub("^%s+", ""):gsub("%s+$", "")
        word = word:gsub("[^%a%'%- ]", "")
        if word == "" then
            ShowToast("Type a word into the Celestial Lexicon first", "warning")
            return
        end
        panel.Input.Text = word
        if LexiconCache[word] then
            RenderLexiconResult(word, LexiconCache[word], true)
            return
        end

        lexiconRequestToken = lexiconRequestToken + 1
        local token = lexiconRequestToken
        panel.Word.Text = word
        panel.Phonetic.Text = "reading two trusted sources..."
        panel.Source.Text = "WEB SCAN IN PROGRESS  /  SOLVER REMAINS RESPONSIVE"
        panel.Source.TextColor3 = THEME.Gold
        panel.Search.Text = "READING"
        SetLexiconBody("The book guardian is gathering definitions and encyclopedia context.\n\nThis request runs outside the turn solver and will time out safely if the executor blocks web access.")
        AnimateGuardian(true)

        task.spawn(function()
            local encodedWord = UrlEncode(word)
            local dictBody, openBody = nil, nil
            local remaining = 2
            task.spawn(function()
                dictBody = HttpGetText("https://api.dictionaryapi.dev/api/v2/entries/en/" .. encodedWord)
                remaining = remaining - 1
            end)
            task.spawn(function()
                openBody = HttpGetText("https://en.wikipedia.org/w/api.php?action=opensearch&search=" .. encodedWord .. "&limit=3&namespace=0&format=json&origin=*")
                remaining = remaining - 1
            end)

            local deadline = tick() + 8
            while remaining > 0 and tick() < deadline and token == lexiconRequestToken and not unloaded do
                task.wait(0.05)
            end
            if token ~= lexiconRequestToken or unloaded then return end

            local openData = DecodeJson(openBody)
            local wikiTitle = type(openData) == "table" and type(openData[2]) == "table" and openData[2][1] or nil
            local extractData = nil
            if wikiTitle then
                local extractBody = HttpGetText("https://en.wikipedia.org/w/api.php?action=query&format=json&origin=*&prop=extracts&exintro=1&explaintext=1&redirects=1&titles=" .. UrlEncode(wikiTitle))
                if token ~= lexiconRequestToken or unloaded then return end
                extractData = DecodeJson(extractBody)
            end

            local dictionary, phonetic = ParseDictionary(DecodeJson(dictBody))
            local parsedTitle, wikipedia, sourceUrl = ParseWikipedia(openData, extractData)
            local result = {
                dictionary = dictionary,
                phonetic = phonetic or "",
                wikiTitle = parsedTitle,
                wikipedia = wikipedia,
                sourceUrl = sourceUrl,
                localWord = LocalVaultContains(word)
            }
            LexiconCache[word] = result
            if token ~= lexiconRequestToken or unloaded then return end
            RenderLexiconResult(word, result, false)
            if not dictionary and not wikipedia then
                panel.Source.Text = "WEB ACCESS LIMITED  /  LOCAL VAULT CHECKED"
                panel.Source.TextColor3 = THEME.Warning
            end
        end)
    end

    panel.Search.MouseButton1Click:Connect(LookupWord)
    panel.Input.FocusLost:Connect(function(enterPressed)
        if enterPressed then LookupWord() end
    end)
    panel.Input.Focused:Connect(function()
        TweenService:Create(searchStroke, TweenInfo.new(0.18), {Color = THEME.Gold, Transparency = 0.02}):Play()
    end)
    panel.Input.FocusLost:Connect(function()
        TweenService:Create(searchStroke, TweenInfo.new(0.18), {Color = THEME.Border, Transparency = 0.28}):Play()
    end)

    local visibilityToken = 0
    local function SetLexiconShown(shown)
        AuxUI.LexiconOpen = shown
        visibilityToken = visibilityToken + 1
        local token = visibilityToken
        local rest = panel.Frame.Position
        local tucked = UDim2.new(rest.X.Scale, rest.X.Offset - 18, rest.Y.Scale, rest.Y.Offset + 12)
        if shown then
            panel.Frame.Visible = true
            panel.Frame.Position = tucked
            panel.Frame.GroupTransparency = 1
            TweenService:Create(panel.Frame, TweenInfo.new(0.34, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                Position = rest,
                GroupTransparency = 0
            }):Play()
            AnimateGuardian(false)
            task.defer(function() panel.Input:CaptureFocus() end)
        else
            lexiconRequestToken = lexiconRequestToken + 1
            TweenService:Create(panel.Frame, TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.In), {
                Position = tucked,
                GroupTransparency = 1
            }):Play()
            task.delay(0.23, function()
                if visibilityToken == token and panel.Frame.Parent then panel.Frame.Visible = false end
            end)
        end
        if AuxUI.SyncModeRail then AuxUI.SyncModeRail() end
    end

    panel.Close.MouseButton1Click:Connect(function() SetLexiconShown(false) end)
    AuxUI.ToggleLexicon = function()
        if AuxUI.Responsive then AuxUI.Responsive() end
        SetLexiconShown(not AuxUI.LexiconOpen)
    end
    AuxUI.LexiconPanel = panel
    EnableDragging(panel.Frame, panel.Header)
end)()

local function SetupPhantomBox(box, placeholder)
    box.Text = placeholder
    box.TextColor3 = THEME.SubText

    box.Focused:Connect(function()
        if box.Text == placeholder then
            box.Text = ""
            box.TextColor3 = THEME.Text
        end
    end)

    box.FocusLost:Connect(function()
        if box.Text == "" then
            box.Text = placeholder
            box.TextColor3 = THEME.SubText
        end
    end)
end

