local function RefreshCustomWords()
    for _, c in ipairs(CWScroll:GetChildren()) do
        if c:IsA("GuiButton") then c:Destroy() end
    end
    
    local queryRaw = CWSearchBox.Text
    local query = (queryRaw == "Search words...") and "" or queryRaw:lower():gsub("’", "'"):gsub("[%s%c]+", "")
    
    local list = Config.CustomWords or {}
    local shownCount = 0
    
    for i, w in ipairs(list) do
        if query == "" or w:find(query, 1, true) then
            shownCount = shownCount + 1
            local row = Instance.new("TextButton", CWScroll)
            row.Size = UDim2.new(1, -8, 0, 32)
            row.BackgroundColor3 = (shownCount % 2 == 0) and THEME.Blush or THEME.Lavender
            row.BackgroundTransparency = 0.2
            row.BorderSizePixel = 0
            row.Text = ""
            row.AutoButtonColor = false
            Instance.new("UICorner", row).CornerRadius = UDim.new(0, 11)
            
            row.MouseButton1Click:Connect(function()
                SmartType(w, lastDetected, true, true)
                Tween(row, {BackgroundColor3 = THEME.Accent}, 0.2)
                task.delay(0.2, function()
                     Tween(row, {BackgroundColor3 = (shownCount % 2 == 0) and THEME.Blush or THEME.Lavender}, 0.2)
                end)
            end)
            
            local lbl = Instance.new("TextLabel", row)
            lbl.Text = w
            lbl.Font = Enum.Font.Gotham
            lbl.TextSize = 12
            lbl.TextColor3 = THEME.Text
            lbl.Size = UDim2.new(1, -30, 1, 0)
            lbl.Position = UDim2.new(0, 5, 0, 0)
            lbl.BackgroundTransparency = 1
            lbl.TextXAlignment = Enum.TextXAlignment.Left

            -- Removed nested invisible button to fix click handling
            
            local del = Instance.new("TextButton", row)
            del.Text = "X"
            del.Font = Enum.Font.GothamBold
            del.TextSize = 11
            del.TextColor3 = THEME.Danger
            del.Size = UDim2.new(0, 22, 1, 0)
            del.Position = UDim2.new(1, -22, 0, 0)
            del.BackgroundTransparency = 1
            
            del.MouseButton1Click:Connect(function()
                table.remove(Config.CustomWords, i)
                SaveConfig()
                if not Blacklist[w] and not UsedWords[w] then AdjustPrefixLiveCounts(w, -1) end
                Blacklist[w] = nil
                UsedWords[w] = nil
                for wordIndex = #Words, 1, -1 do
                    if Words[wordIndex] == w then table.remove(Words, wordIndex) end
                end
                local first = w:sub(1, 1)
                local wordBucket = Buckets and Buckets[first]
                if wordBucket then
                    for wordIndex = #wordBucket, 1, -1 do
                        if wordBucket[wordIndex] == w then table.remove(wordBucket, wordIndex) end
                    end
                end
                if AuxUI.RebuildPunctuationIndexes then AuxUI.RebuildPunctuationIndexes() end
                forceUpdateList = true
                RefreshCustomWords()
                ShowToast("Removed: " .. w, "warning")
            end)
        end
    end
    CWScroll.CanvasSize = UDim2.new(0, 0, 0, shownCount * 34)
end

CWSearchBox:GetPropertyChangedSignal("Text"):Connect(RefreshCustomWords)

CWAddBtn.MouseButton1Click:Connect(function()
    local text = CWAddBox.Text
    if text == "Add new word..." then return end
    
    text = AuxUI.NormalizeWordText(text)
    if #text < 2 then return end
    
    if not Config.CustomWords then Config.CustomWords = {} end
    
    for _, w in ipairs(Config.CustomWords) do
        if w == text then
            ShowToast("Word already in custom list!", "warning")
            return
        end
    end
    
    local existsInMain = false
    local c = text:sub(1,1)
    if Buckets and Buckets[c] then
        for _, w in ipairs(Buckets[c]) do
            if w == text then existsInMain = true break end
        end
    end
    
    if existsInMain then
         ShowToast("Word already in main dictionary!", "error")
         return
    end

    table.insert(Config.CustomWords, text)
    SaveConfig()
    
    table.insert(Words, text)
    AdjustPrefixLiveCounts(text, 1)
    if c == "" then c = "#" end
    Buckets[c] = Buckets[c] or {}
    table.insert(Buckets[c], text)
    table.sort(Buckets[c])
    if AuxUI.RebuildPunctuationIndexes then AuxUI.RebuildPunctuationIndexes() end
    
    CWAddBox.Text = ""
    CWAddBox:ReleaseFocus()
    RefreshCustomWords()
    ShowToast("Added custom word: " .. text, "success")
end)

RefreshCustomWords()
end
SetupCustomWordsManager()

