local function CalculateDelay()
    local charsPerMin = currentCPM
    local baseDelay = 60 / charsPerMin
    local variance = baseDelay * 0.4
    return useHumanization and (baseDelay + math.random()*variance - (variance/2)) or baseDelay
end

local KEY_POS = {}
do
    local row1 = "qwertyuiop"
    local row2 = "asdfghjkl"
    local row3 = "zxcvbnm"
    for i = 1, #row1 do
        KEY_POS[row1:sub(i,i)] = {x = i, y = 1}
    end
    for i = 1, #row2 do
        KEY_POS[row2:sub(i,i)] = {x = i + 0.5, y = 2}
    end
    for i = 1, #row3 do
        KEY_POS[row3:sub(i,i)] = {x = i + 1, y = 3}
    end
end

local function KeyDistance(a, b)
    if not a or not b then return 1 end
    a = a:lower()
    b = b:lower()
    local pa = KEY_POS[a]
    local pb = KEY_POS[b]
    if not pa or not pb then return 1 end
    local dx = pa.x - pb.x
    local dy = pa.y - pb.y
    return math.sqrt(dx*dx + dy*dy)
end

local lastKey = nil
local function CalculateDelayForKeys(prevChar, nextChar)
    if isBlatant then 
        return 60 / currentCPM 
    end

    local charsPerMin = currentCPM
    local baseDelay = 60 / charsPerMin
    
    local variance = baseDelay * 0.35
    local extra = 0
    
    if useHumanization and useFingerModel and prevChar and nextChar and prevChar ~= "" then
        local dist = KeyDistance(prevChar, nextChar)
        extra = dist * 0.018 * (550 / math.max(150, currentCPM))
        
        local pa = KEY_POS[prevChar:lower()]
        local pb = KEY_POS[nextChar:lower()]
        if pa and pb then
            if (pa.x <= 5 and pb.x <= 5) or (pa.x > 5 and pb.x > 5) then
                extra = extra * 0.8
            end
        end
    end

    if useHumanization then
        local r = (math.random() + math.random() + math.random()) / 3
        local noise = (r * 2 - 1) * variance
        return math.max(0.005, baseDelay + extra + noise)
    else
        return baseDelay
    end
end

local VirtualUser = game:GetService("VirtualUser")
local isMobile = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled

local function GetKeyCode(char)
    local layout = Config.KeyboardLayout or "QWERTY"
    
    if type(char) == "string" and #char == 1 then
        char = char:lower()
        if char == "'" then return Enum.KeyCode.Quote end
        if char == "-" then return Enum.KeyCode.Minus end
        if layout == "QWERTZ" then
            if char == "z" then return Enum.KeyCode.Y end
            if char == "y" then return Enum.KeyCode.Z end
        elseif layout == "AZERTY" then
            if char == "a" then return Enum.KeyCode.Q end
            if char == "q" then return Enum.KeyCode.A end
            if char == "z" then return Enum.KeyCode.W end
            if char == "w" then return Enum.KeyCode.Z end
            if char == "m" then return Enum.KeyCode.Semicolon end -- M is often next to L
            -- NOTE: AZERTY is tricky because M can vary, but standard AZERTY FR places M right of L (where semi-colon is on QWERTY)
            -- However, many games might use scan codes where M is actually comma or something else depending on the specific AZERTY variant.
            -- For standard AZERTY (France), M is indeed usually where ; is.
        end
        return Enum.KeyCode[char:upper()]
    end
    return nil
end

local function SimulateKey(input)
    if typeof(input) == "string" and #input == 1 then
         local char = input
         local vimSuccess = pcall(function()
             VirtualInputManager:SendTextInput(char)
         end)
         
         if not vimSuccess then
             -- Fallback for executors that don't support SendTextInput or for keycodes
             local key
             pcall(function() key = GetKeyCode(input) end)
             if not key then pcall(function() key = Enum.KeyCode[input:upper()] end) end
             
             if key then
                 pcall(function()
                     VirtualInputManager:SendKeyEvent(true, key, false, game)
                     task.wait(0.01)
                     VirtualInputManager:SendKeyEvent(false, key, false, game)
                 end)
             end
         end
         return
    end

    local key
    if typeof(input) == "EnumItem" then
        key = input
    else
        pcall(function() key = Enum.KeyCode[input:upper()] end)
    end

    if key then
        local baseHold = math.clamp(12 / currentCPM, 0.015, 0.05)
        local hold = isBlatant and 0.002 or (baseHold + (math.random() * 0.01) - 0.005)

        local vimSuccess = pcall(function()
            VirtualInputManager:SendKeyEvent(true, key, false, game)
            task.wait(hold)
            VirtualInputManager:SendKeyEvent(false, key, false, game)
        end)

        if not vimSuccess then
            pcall(function()
                VirtualUser:TypeKey(key)
            end)
        end
    end
end

local function Backspace(count)
    count = math.max(0, math.floor(tonumber(count) or 0))
    if count == 0 then return end

    local focused = UserInputService:GetFocusedTextBox()
    local delivered = false
    local key = Enum.KeyCode.Backspace
    for i = 1, count do
        local ok = pcall(function()
            VirtualInputManager:SendKeyEvent(true, key, false, game)
            VirtualInputManager:SendKeyEvent(false, key, false, game)
        end)
        if ok then
            delivered = true
        else
            pcall(function() VirtualUser:TypeKey(key) end)
        end
        if i % 12 == 0 then task.wait() end
    end

    -- Directly assigning Text is fast, but this game keeps a separate tile
    -- model that only observes real Backspace input. Use assignment strictly
    -- as an executor fallback when no input event could be delivered.
    if not delivered and focused and focused:IsDescendantOf(game) and focused.TextEditable then
        local text = focused.Text
        focused.Text = text:sub(1, math.max(0, #text - count))
    end
    lastKey = nil
end

local function PressEnter()
    SimulateKey(Enum.KeyCode.Return)
    lastKey = nil
end

local function GetGameTextBox()
    local player = Players.LocalPlayer
    local gui = player and player:FindFirstChild("PlayerGui")
    local inGame = gui and gui:FindFirstChild("InGame")
    if inGame then
        local frame = inGame:FindFirstChild("Frame")
        if frame then
             for _, c in ipairs(frame:GetDescendants()) do
                 if c:IsA("TextBox") and c.Visible then return c end
             end
        end
        for _, c in ipairs(inGame:GetDescendants()) do
             if c:IsA("TextBox") and c.Visible then return c end
        end
    end
    return UserInputService:GetFocusedTextBox()
end

-- Atomically discard rows/scans painted for an older prompt. The replacement
-- list is coalesced through the normal 25 Hz loop instead of being rebuilt in
-- the click callback, keeping the handoff responsive on phones.
AuxUI.QueueLivePromptRefresh = function(liveDetected, liveRequired)
    liveDetected = AuxUI.NormalizeWordText(liveDetected)
    liveRequired = AuxUI.NormalizeWordText(liveRequired)
    CancelAutoPlaySchedule()
    sideScanGeneration = sideScanGeneration + 1
    trapScanPending = false
    currentBestMatch = nil
    lastDetected = liveDetected
    lastRequiredLetter = liveRequired
    listUpdatePending = true
    forceUpdateList = false
    lastInputTime = 0
end

-- Restore only the required 1-4 letter game prompt, never a submitted word.
-- Real key events keep the game's visible tiles and its internal input model
-- synchronized; the old direct Text assignment could update only one of them.
AuxUI.RestoreGamePrompt = function(expectedRequired, reason)
    expectedRequired = AuxUI.NormalizeWordText(expectedRequired)
    local stillMyTurn, liveRequired = GetTurnInfo()
    liveRequired = AuxUI.NormalizeWordText(liveRequired)
    if not stillMyTurn then return false end
    if expectedRequired == "" then expectedRequired = liveRequired end
    if expectedRequired == "" then return false end
    if liveRequired ~= "" and liveRequired ~= expectedRequired then return false end

    local ownsTypingLock = not isTyping
    if ownsTypingLock then
        isTyping = true
        lastTypingStart = tick()
    end

    local targetBox = GetGameTextBox()
    if targetBox then
        targetBox:CaptureFocus()
        task.wait(0.01)
    end

    local detectedNow = GetCurrentGameWord()
    local boxText = targetBox and AuxUI.NormalizeWordText(targetBox.Text) or ""
    Backspace(math.max(#detectedNow, #boxText))
    RunService.Heartbeat:Wait()

    -- Some versions of the game lock the required prefix against deletion.
    -- Re-read after clearing and append only what is actually missing.
    local remaining = GetCurrentGameWord()
    if remaining ~= "" and expectedRequired:sub(1, #remaining) ~= remaining then
        Backspace(#remaining)
        RunService.Heartbeat:Wait()
        remaining = GetCurrentGameWord()
    end
    local missing = expectedRequired
    if remaining ~= "" and expectedRequired:sub(1, #remaining) == remaining then
        missing = expectedRequired:sub(#remaining + 1)
    end
    for index = 1, #missing do
        SimulateKey(missing:sub(index, index))
    end

    lastWordCheck = 0
    cachedDetected = expectedRequired
    cachedCensored = false
    AuxUI.QueueLivePromptRefresh(expectedRequired, liveRequired ~= "" and liveRequired or expectedRequired)
    StatusText.Text = reason or ("prompt restored  ·  " .. expectedRequired)
    StatusText.TextColor3 = THEME.Warning
    Tween(StatusDot, {BackgroundColor3 = THEME.Warning})

    if ownsTypingLock then isTyping = false end
    return true
end

-- Submission verification is fully asynchronous. It waits through one extra
-- network beat, distinguishes a dropped key from a server rejection, and only
-- restores the field while the same prompt is still active.
AuxUI.VerifySubmittedWord = function(targetWord, promptSignature, originalRequired)
    AuxUI.SubmissionVerifyGeneration = (AuxUI.SubmissionVerifyGeneration or 0) + 1
    local generation = AuxUI.SubmissionVerifyGeneration
    originalRequired = AuxUI.NormalizeWordText(originalRequired)
    task.delay(0.34, function()
        if unloaded or generation ~= AuxUI.SubmissionVerifyGeneration then return end

        local stillMyTurn, liveRequired = GetTurnInfo()
        liveRequired = AuxUI.NormalizeWordText(liveRequired)
        local samePrompt = originalRequired == "" or liveRequired == "" or liveRequired == originalRequired
        if stillMyTurn and samePrompt then
            task.wait(0.22)
            if unloaded or generation ~= AuxUI.SubmissionVerifyGeneration then return end
            stillMyTurn, liveRequired = GetTurnInfo()
            liveRequired = AuxUI.NormalizeWordText(liveRequired)
            samePrompt = originalRequired == "" or liveRequired == "" or liveRequired == originalRequired
        end

        if stillMyTurn and samePrompt then
            local currentCheck = GetCurrentGameWord()
            local inputDrifted = currentCheck ~= targetWord
                and currentCheck ~= originalRequired
                and (originalRequired == "" or currentCheck:sub(1, #originalRequired) ~= originalRequired)
            if inputDrifted then
                if AuxUI.RestoreRuntimeWord then AuxUI.RestoreRuntimeWord(targetWord) end
            else
                BlacklistRuntimeWord(targetWord)
            end
            if AuxUI.SubmittedPromptSignature == promptSignature then
                AuxUI.SubmittedPromptSignature = nil
            end

            local shouldRestore = currentCheck == targetWord or inputDrifted
            if shouldRestore then
                AuxUI.RestoreGamePrompt(originalRequired, inputDrifted
                    and "input resynced  ·  original prompt restored"
                    or "not accepted  ·  original prompt restored")
            else
                StatusText.Text = "not accepted  ·  choose another word"
                StatusText.TextColor3 = THEME.Warning
            end
        elseif StatusText.Text == "word sent  ·  checking quietly" then
            StatusText.Text = "word accepted  ✓"
            StatusText.TextColor3 = THEME.Success
        end
    end)
end

SmartType = function(targetWord, currentDetected, isCorrection, bypassTurn, skipOpeningPause, expectedPrompt)
    if unloaded then return end
    targetWord = AuxUI.NormalizeWordText(targetWord)
    currentDetected = AuxUI.NormalizeWordText(currentDetected)
    if targetWord == "" then return end

    -- Rows are virtualized and may survive for one painted frame while the
    -- game hands the turn to a new prompt. Re-read the authoritative prefix at
    -- click time and refuse any word belonging to the previous prompt.
    local liveTurnAtClick, originalRequired = GetTurnInfo()
    originalRequired = AuxUI.NormalizeWordText(originalRequired)
    if not bypassTurn then
        local liveDetected = GetCurrentGameWord()
        if not liveTurnAtClick then
            AuxUI.QueueLivePromptRefresh(liveDetected, originalRequired)
            StatusText.Text = "click cancelled  ·  the turn already changed"
            StatusText.TextColor3 = THEME.Warning
            return
        end
        if originalRequired ~= "" and targetWord:sub(1, #originalRequired) ~= originalRequired then
            AuxUI.QueueLivePromptRefresh(liveDetected, originalRequired)
            AuxUI.RestoreGamePrompt(originalRequired, "new prompt caught  ·  stale row cancelled")
            return
        end

        if liveDetected ~= "" and targetWord:sub(1, #liveDetected) ~= liveDetected then
            -- The required prefix is still current, but the editable tiles are
            -- holding an old/rejected word. Restore the anchor before typing.
            if originalRequired ~= "" and targetWord:sub(1, #originalRequired) == originalRequired then
                AuxUI.RestoreGamePrompt(originalRequired, "input realigned  ·  continuing from the live prompt")
                currentDetected = originalRequired
            else
                AuxUI.QueueLivePromptRefresh(liveDetected, originalRequired)
                StatusText.Text = "click cancelled  ·  results refreshed"
                StatusText.TextColor3 = THEME.Warning
                return
            end
        elseif liveDetected ~= "" then
            currentDetected = liveDetected
        end
    end

    if AuxUI.SubmittedPromptSignature == currentDetected and (tick() - AuxUI.LastSubmissionAt) < 0.38 then return end
    
    if isTyping then
        if (tick() - lastTypingStart) > 15 then
            isTyping = false
            isAutoPlayScheduled = false
            StatusText.Text = "typing gently reset"
            StatusText.TextColor3 = THEME.Warning
        else
            return
        end
    end

    isTyping = true
    lastTypingStart = tick()
    local acceptedSubmission = false

    -- One shared opening pause fixes the old split behavior where the slider
    -- affected Auto Play scheduling and typo recovery, but did nothing when a
    -- result row was clicked. It delays an explicit typing action only; it
    -- never starts typing on its own.
    local openingPause = skipOpeningPause and 0 or math.max(0, tonumber(thinkDelayCurrent) or 0)
    if openingPause > 0 then
        StatusText.Text = string.format("holding for %.2fs before typing...", openingPause)
        StatusText.TextColor3 = THEME.Gold
        Tween(StatusDot, {BackgroundColor3 = THEME.Gold})
        task.wait(openingPause)
        if unloaded then
            isTyping = false
            return
        end
        if not bypassTurn then
            local stillMyTurn, requiredAfterPause = GetTurnInfo()
            requiredAfterPause = AuxUI.NormalizeWordText(requiredAfterPause)
            if not stillMyTurn then
                isTyping = false
                StatusText.Text = "pause ended after the turn changed"
                StatusText.TextColor3 = THEME.Warning
                return
            end
            if originalRequired ~= "" and requiredAfterPause ~= "" and requiredAfterPause ~= originalRequired then
                isTyping = false
                AuxUI.QueueLivePromptRefresh(GetCurrentGameWord(), requiredAfterPause)
                StatusText.Text = "pause cancelled  ·  a new prompt arrived"
                StatusText.TextColor3 = THEME.Warning
                return
            end
            local promptAfterPause = GetCurrentGameWord()
            local expectedAfterPause = expectedPrompt or currentDetected
            if expectedAfterPause and promptAfterPause ~= expectedAfterPause then
                isTyping = false
                StatusText.Text = "pause cancelled · prompt changed"
                StatusText.TextColor3 = THEME.Warning
                return
            end
        end
    end
    
    local targetBox = GetGameTextBox()
    if targetBox then
        targetBox:CaptureFocus()
        task.wait(isBlatant and 0.01 or 0.025)
    end
    
    StatusText.Text = "placing the word..."
    StatusText.TextColor3 = THEME.Accent
    Tween(StatusDot, {BackgroundColor3 = THEME.Accent})

    local success, err = pcall(function()
        if isCorrection then
            local correctionSource = currentDetected
            if targetBox then
                local boxValue = AuxUI.NormalizeWordText(targetBox.Text)
                if boxValue ~= "" or correctionSource == "" then
                    correctionSource = boxValue
                end
            end
            local commonLen = 0
            local minLen = math.min(#targetWord, #correctionSource)
            for i = 1, minLen do
                if targetWord:sub(i,i) == correctionSource:sub(i,i) then
                    commonLen = i
                else
                    break
                end
            end

            local backspaceCount = #correctionSource - commonLen
            if backspaceCount > 0 then
                Backspace(backspaceCount)
                task.wait(isBlatant and 0.01 or 0.04)
            end
            
            local toType = targetWord:sub(commonLen + 1)
            for i = 1, #toType do
                if not bypassTurn and not GetTurnInfo() then
                    -- Double check if turn info is just flickering
                    task.wait(0.05)
                    if not GetTurnInfo() then
                        StatusText.Text = "typing cancelled · turn changed"
                        StatusText.TextColor3 = THEME.Warning
                        return
                    end
                end
                local ch = toType:sub(i, i)
                SimulateKey(ch)
                task.wait(CalculateDelayForKeys(lastKey, ch))
                lastKey = ch
                if useHumanization and not isBlatant and math.random() < 0.03 then
                    task.wait(0.15 + math.random() * 0.45)
                end
            end

            -- Pre-submission verify
            local finalCheck = GetGameTextBox()
            if not riskyMistakes then
                task.wait(isBlatant and 0.01 or 0.035)
                finalCheck = GetGameTextBox()
                if finalCheck and AuxUI.NormalizeWordText(finalCheck.Text) ~= targetWord then
                    local restored = AuxUI.RestoreGamePrompt(originalRequired,
                        "a key slipped  ·  original prompt restored")
                    if not restored then
                        Backspace(#finalCheck.Text)
                        forceUpdateList = true
                    end
                    isTyping = false
                    return
                end
            end

            PressEnter()
            AuxUI.SubmittedPromptSignature = currentDetected
            AuxUI.LastSubmissionAt = tick()
            StatusText.Text = "word sent  ·  checking quietly"
            StatusText.TextColor3 = THEME.Accent
            acceptedSubmission = true
            RemoveRuntimeWord(targetWord)
            isMyTurnLogDetected = false
            AuxUI.VerifySubmittedWord(targetWord, currentDetected, originalRequired)
            task.wait()
        else
            local liveInput = currentDetected
            if targetBox then
                local boxValue = AuxUI.NormalizeWordText(targetBox.Text)
                if boxValue ~= "" or liveInput == "" then liveInput = boxValue end
            end
            if liveInput ~= "" and targetWord:sub(1, #liveInput) ~= liveInput then
                Backspace(#liveInput)
                task.wait(isBlatant and 0.01 or 0.04)
                liveInput = ""
            end
            local missingPart = ""
            if targetWord:sub(1, #liveInput) == liveInput then
                missingPart = targetWord:sub(#liveInput + 1)
            else
                missingPart = targetWord
            end

            local letters = "abcdefghijklmnopqrstuvwxyz"
            for i = 1, #missingPart do
                if not bypassTurn and not GetTurnInfo() then
                     -- Double check if turn info is just flickering
                     task.wait(0.05)
                     if not GetTurnInfo() then
                         StatusText.Text = "typing cancelled · turn changed"
                         StatusText.TextColor3 = THEME.Warning
                         return
                     end
                end
                local ch = missingPart:sub(i, i)
                if errorRate > 0 and (math.random() < (errorRate / 100)) then
                    local typoChar
                    repeat
                        local idx = math.random(1, #letters)
                        typoChar = letters:sub(idx, idx)
                    until typoChar ~= ch
                    SimulateKey(typoChar)
                    
                    if riskyMistakes then
                         task.wait(0.05 + math.random() * 0.1)
                         PressEnter()
                    end

                    task.wait(CalculateDelayForKeys(lastKey, typoChar))
                    lastKey = typoChar
                    local realize = thinkDelayCurrent * (0.6 + math.random() * 0.8)
                    task.wait(realize)
                    SimulateKey(Enum.KeyCode.Backspace)
                    lastKey = nil
                    task.wait(0.05 + math.random() * 0.08)
                    SimulateKey(ch)
                    task.wait(CalculateDelayForKeys(lastKey, ch))
                    lastKey = ch
                else
                    SimulateKey(ch)
                    task.wait(CalculateDelayForKeys(lastKey, ch))
                    lastKey = ch
                end
                if useHumanization and not isBlatant and math.random() < 0.03 then
                    task.wait(0.12 + math.random() * 0.5)
                end
            end

            -- Pre-submission verify
            if not riskyMistakes then
                -- Wait a moment for last character to register
                task.wait(isBlatant and 0.01 or 0.035)
                local finalCheck = GetGameTextBox()
                if finalCheck and AuxUI.NormalizeWordText(finalCheck.Text) ~= targetWord then
                    local restored = AuxUI.RestoreGamePrompt(originalRequired,
                        "a key slipped  ·  original prompt restored")
                    if not restored then
                        Backspace(#finalCheck.Text)
                        forceUpdateList = true
                    end
                    isTyping = false
                    return
                end
            end

            PressEnter()
            AuxUI.SubmittedPromptSignature = currentDetected
            AuxUI.LastSubmissionAt = tick()
            StatusText.Text = "word sent  ·  checking quietly"
            StatusText.TextColor3 = THEME.Accent
            acceptedSubmission = true
            RemoveRuntimeWord(targetWord)
            isMyTurnLogDetected = false
            AuxUI.VerifySubmittedWord(targetWord, currentDetected, originalRequired)
            task.wait()
        end
    end)
    isTyping = false
    if not success then
        CancelAutoPlaySchedule()
        StatusText.Text = "typing bridge paused · no keys were queued"
        StatusText.TextColor3 = THEME.Warning
        pcall(function() warn("[LRRXWARE] typing bridge: " .. tostring(err)) end)
    end
    if acceptedSubmission then
        task.defer(function()
            if AuxUI.PlayCharacterAction then AuxUI.PlayCharacterAction("celebrate", true) end
        end)
        -- Let the turn edge supply the next prompt. Do not rebuild the old
        -- prompt and immediately throw that work away.
        sideScanGeneration = sideScanGeneration + 1
        trapScanPending = false
        listUpdatePending = false
        currentBestMatch = nil
    else
        forceUpdateList = true
    end
end

-- The think slider belongs to the Auto Play scheduler, not the keystroke
-- routine. That keeps the UI responsive during the wait and lets prompt/turn
-- changes cancel the action before a single key is sent.
local function ScheduleAutoPlay(targetWord, snapshotDetected, snapshotRequired)
    CancelAutoPlaySchedule()
    autoPlayGeneration = autoPlayGeneration + 1
    local myGeneration = autoPlayGeneration
    isAutoPlayScheduled = true

    task.spawn(function()
        local delaySeconds = math.max(0, tonumber(thinkDelayCurrent) or 0)
        local deadline = tick() + delaySeconds

        while tick() < deadline do
            if unloaded or not autoPlay or myGeneration ~= autoPlayGeneration then return end
            local stillMyTurn, currentRequired = GetTurnInfo()
            local currentPrompt = GetCurrentGameWord()
            if not stillMyTurn or currentPrompt ~= snapshotDetected
                or (snapshotRequired ~= "" and currentRequired ~= snapshotRequired) then
                if myGeneration == autoPlayGeneration then CancelAutoPlaySchedule() end
                return
            end

            local remaining = deadline - tick()
            StatusText.Text = string.format("thinking  ·  %.2fs", math.max(0, remaining))
            StatusText.TextColor3 = THEME.Gold
            task.wait(math.min(0.04, math.max(0.005, remaining)))
        end

        if unloaded or not autoPlay or isTyping or myGeneration ~= autoPlayGeneration then return end
        local stillMyTurn, currentRequired = GetTurnInfo()
        local currentPrompt = GetCurrentGameWord()
        if not stillMyTurn or currentPrompt ~= snapshotDetected
            or (snapshotRequired ~= "" and currentRequired ~= snapshotRequired)
            or UsedWords[targetWord] or Blacklist[targetWord] then
            if myGeneration == autoPlayGeneration then CancelAutoPlaySchedule() end
            return
        end

        SmartType(targetWord, snapshotDetected, false, false, true, snapshotDetected)
        if myGeneration == autoPlayGeneration then
            isAutoPlayScheduled = false
        end
    end)
end

local function GetMatchLength(str, prefix)
    local len = 0
    local max = math.min(#str, #prefix)
    for i = 1, max do
        local pb = string.byte(prefix, i)
        if pb == 35 or pb == string.byte(str, i) then
            len = i
        else
            break
        end
    end
    return len
end

local function BinarySearchStart(list, prefix)
    local left = 1
    local right = #list
    local result = -1
    local pLen = #prefix

    while left <= right do
        local mid = math.floor((left + right) / 2)
        local word = list[mid]
        local sub = word:sub(1, pLen)

        if sub == prefix then
            result = mid
            right = mid - 1
        elseif sub < prefix then
            left = mid + 1
        else
            right = mid - 1
        end
    end

    return result
end

-- Select the smallest complete index for a prompt. Normal words keep their
-- first-letter O(log n) path; punctuation-only prompts use compact indexes.
AuxUI.GetSearchBucket = function(rawPrefix)
    local prefix = AuxUI.NormalizeWordText(rawPrefix)
    local first = prefix:sub(1, 1)
    if first == "-" then return AuxUI.PunctuationBuckets.Hyphen end
    if first == "'" then return AuxUI.PunctuationBuckets.Apostrophe end
    if prefix == "" and sortMode == "Hyphen" then return AuxUI.PunctuationBuckets.Hyphen end
    if prefix == "" and sortMode == "Apostrophe" then return AuxUI.PunctuationBuckets.Apostrophe end
    if first ~= "" and first ~= "#" and Buckets then return Buckets[first] or {} end
    return Words
end

-- Restore every word disabled during this execution. Since the sorted
-- dictionary never moves, reset only clears flags and restores prefix counts.
AuxUI.ResetSession = function()
    if isTyping then
        ShowToast("wait for the current word to finish", "warning")
        return
    end

    local restored = 0
    local restoredWords = {}
    for word in pairs(UsedWords) do
        if not restoredWords[word] then
            restoredWords[word] = true
            AdjustPrefixLiveCounts(word, 1)
            restored = restored + 1
        end
    end
    for word in pairs(Blacklist) do
        if not restoredWords[word] then
            restoredWords[word] = true
            AdjustPrefixLiveCounts(word, 1)
            restored = restored + 1
        end
    end

    table.clear(UsedWords)
    table.clear(Blacklist)
    table.clear(RandomOrderCache)
    table.clear(RandomPriority)
    currentBestMatch = nil
    CancelAutoPlaySchedule()
    AuxUI.SubmissionVerifyGeneration = (AuxUI.SubmissionVerifyGeneration or 0) + 1
    AuxUI.SubmittedPromptSignature = nil
    AuxUI.LastSubmissionAt = 0
    forceUpdateList = true
    lastInputTime = 0

    StatusText.Text = restored > 0 and ("session restored · " .. restored .. " words returned") or "session already fresh"
    StatusText.TextColor3 = THEME.Success
    Tween(StatusDot, {BackgroundColor3 = THEME.Success})
    ShowToast(restored > 0 and ("Restored " .. restored .. " session words") or "All session words are already available", "success")
end

