    local function RenderSidePanel(panel)
        local rowHeight = 54
        local firstIndex = math.max(1, math.floor(panel.Scroll.CanvasPosition.Y / rowHeight) + 1)
        local poolSize = math.max(12, math.ceil(panel.Scroll.AbsoluteSize.Y / rowHeight) + 4)

        for slot = 1, poolSize do
            local index = firstIndex + slot - 1
            local word = panel.Words[index]
