                        aura.Transparency = NumberSequence.new(0.03, 0.38)
                        aura.Rotation = 10
                        local outline = Instance.new("UIStroke", button)
                        outline.Name = "_outline"
                        outline.Color = THEME.Border
                        outline.Transparency = 0.24
                        local dot = Instance.new("Frame", button)
                        dot.Name = "Dot"
                        dot.Size = UDim2.fromOffset(4, 28)
                        dot.Position = UDim2.new(0, 10, 0.5, -14)
                        dot.BackgroundColor3 = panel.Kind == "trap" and THEME.Danger or THEME.Accent
                        dot.BorderSizePixel = 0
                        Instance.new("UICorner", dot).CornerRadius = UDim.new(1, 0)
                        local glyph = Instance.new("TextLabel", button)
                        glyph.Name = "RowSigil"
                        glyph.Size = UDim2.fromOffset(22, 22)
                        glyph.Position = UDim2.new(0, 19, 0.5, -11)
                        glyph.BackgroundTransparency = 1
                        glyph.Text = panel.Kind == "trap" and "T" or "S"
                        glyph.TextColor3 = panel.Kind == "trap" and THEME.Danger or THEME.Accent
                        glyph.Font = Enum.Font.Garamond
                        glyph.TextSize = 15
                    end
                    local label = Instance.new("TextLabel", button)
                    label.Name = "Label"
                    label.Size = UDim2.new(1, -138, 1, 0)
                    label.Position = UDim2.new(0, 47, 0, 0)
                    label.BackgroundTransparency = 1
                    label.TextColor3 = THEME.Text
                    label.Font = AuxUI.GetFontProfile().Word
                    label.TextSize = THEME.Motif == "petal" and 15 or 12
                    label.TextXAlignment = Enum.TextXAlignment.Left
                    label.RichText = true
                    local badge = Instance.new("TextLabel", button)
                    badge.Name = "Badge"
                    badge.Size = UDim2.fromOffset(82, 24)
                    badge.Position = UDim2.new(1, -90, 0.5, -12)
                    badge.BackgroundColor3 = panel.Kind == "trap" and THEME.Blush or THEME.Lavender
                    badge.BackgroundTransparency = 0.18
                    badge.TextColor3 = panel.Kind == "trap" and THEME.Danger or THEME.Accent
                    badge.Font = Enum.Font.GothamMedium
                    badge.TextSize = 9
                    Instance.new("UICorner", badge).CornerRadius = UDim.new(1, 0)
                    button.MouseEnter:Connect(function() Tween(button, {BackgroundColor3 = THEME.Blush}) end)
                    button.MouseLeave:Connect(function() Tween(button, {BackgroundColor3 = THEME.Surface}) end)
                    button.MouseButton1Click:Connect(function()
                        local data = panel.ButtonData[button]
                        if data and SmartType then
                            SmartType(data.word, data.detected, true)
                            Tween(button, {BackgroundColor3 = THEME.Sage})
                        end
                    end)
                    table.insert(panel.RowCache, button)
                else
                    button.Visible = true
                    button.Parent = panel.Scroll
                    button.BackgroundColor3 = THEME.Surface
                end

                button.Position = UDim2.new(0.5, 0, 0, (index - 1) * rowHeight)
                panel.ButtonData[button] = {word = word, detected = panel.Detected}
                local panelColor = panel.Kind == "trap" and THEME.Danger or THEME.Accent
                local aura = button:FindFirstChild("_aura")
                if aura then
                    aura.Enabled = Config.RadiantWords == true
                    aura.Color = ColorSequence.new(THEME.Surface, THEME.Surface:Lerp(panelColor, 0.18))
                end
                local outline = button:FindFirstChild("_outline")
                if outline then
                    outline.Color = Config.RadiantWords and panelColor or THEME.Border
                    outline.Transparency = Config.RadiantWords and 0.58 or 0.24
                end
                local highlight = panel.Highlight or ""
                local accentRGB = ColorToRGB(panelColor)
                local textRGB = ColorToRGB(THEME.Text)
                local label = button:FindFirstChild("Label")
                if label then
                    label.Text = "<font color=\"rgb(" .. accentRGB .. ")\">" .. word:sub(1, #highlight) .. "</font>"
                        .. "<font color=\"rgb(" .. textRGB .. ")\">" .. word:sub(#highlight + 1) .. "</font>"
                end
                local badge = button:FindFirstChild("Badge")
                if badge then
                    local meta = panel.Meta[word]
                    if panel.Kind == "trap" and type(meta) == "table" then
                        badge.Text = tostring(meta.prompt) .. " · " .. tostring(meta.count)
                    else
                        badge.Text = "ends · " .. tostring(meta or "-")
                    end
                end
            elseif button then
                button.Visible = false
                panel.ButtonData[button] = nil
            end
        end

        for slot = poolSize + 1, #panel.RowCache do
            panel.RowCache[slot].Visible = false
            panel.ButtonData[panel.RowCache[slot]] = nil
        end
    end

    AuxUI.TrapPanel = CreateSidePanel("trap", 348, 136)
    AuxUI.SpamPanel = CreateSidePanel("spam", 366, 210)
    AuxUI.TrapPanel.Scroll:GetPropertyChangedSignal("CanvasPosition"):Connect(function() RenderSidePanel(AuxUI.TrapPanel) end)
    AuxUI.SpamPanel.Scroll:GetPropertyChangedSignal("CanvasPosition"):Connect(function() RenderSidePanel(AuxUI.SpamPanel) end)

    do
        local spamPanel = AuxUI.SpamPanel
        spamPanel.Input = Instance.new("TextBox", spamPanel.Frame)
        spamPanel.Input.Size = UDim2.new(1, -76, 0, 36)
        spamPanel.Input.Position = UDim2.new(0, 14, 0, 96)
        spamPanel.Input.BackgroundColor3 = THEME.Surface
        spamPanel.Input.Text = ""
        spamPanel.Input.PlaceholderText = "type your own ending..."
        spamPanel.Input.PlaceholderColor3 = THEME.SubText
        spamPanel.Input.TextColor3 = THEME.Text
        spamPanel.Input.Font = Enum.Font.GothamMedium
        spamPanel.Input.TextSize = 11
        spamPanel.Input.ClearTextOnFocus = false
        spamPanel.Input.TextXAlignment = Enum.TextXAlignment.Left
        Instance.new("UICorner", spamPanel.Input).CornerRadius = UDim.new(0, 13)
        local inputPadding = Instance.new("UIPadding", spamPanel.Input)
        inputPadding.PaddingLeft = UDim.new(0, 12)
        local inputStroke = Instance.new("UIStroke", spamPanel.Input)
        inputStroke.Color = THEME.Border
        inputStroke.Transparency = 0.34

        spamPanel.Add = Instance.new("TextButton", spamPanel.Frame)
        spamPanel.Add.Size = UDim2.fromOffset(42, 36)
        spamPanel.Add.Position = UDim2.new(1, -56, 0, 96)
        spamPanel.Add.BackgroundColor3 = THEME.Accent
        spamPanel.Add.Text = "+"
        spamPanel.Add.TextColor3 = Color3.fromRGB(255, 252, 249)
        spamPanel.Add.Font = Enum.Font.GothamBold
        spamPanel.Add.TextSize = 18
        Instance.new("UICorner", spamPanel.Add).CornerRadius = UDim.new(0, 13)

        spamPanel.Chips = Instance.new("ScrollingFrame", spamPanel.Frame)
        spamPanel.Chips.Size = UDim2.new(1, -28, 0, 38)
        spamPanel.Chips.Position = UDim2.new(0, 14, 0, 140)
        spamPanel.Chips.BackgroundTransparency = 1
        spamPanel.Chips.BorderSizePixel = 0
        spamPanel.Chips.ScrollBarThickness = 2
        spamPanel.Chips.ScrollBarImageColor3 = THEME.Accent2
        spamPanel.Chips.ScrollingDirection = Enum.ScrollingDirection.X
        spamPanel.Chips.CanvasSize = UDim2.new(0, 0, 0, 0)

        AuxUI.RefreshSpamChips = function()
            for _, child in ipairs(spamPanel.Chips:GetChildren()) do child:Destroy() end
            local x = 0
            for index, ending in ipairs(Config.SpamEndings) do
                local chipWidth = math.clamp(42 + #ending * 7, 66, 142)
                local chip = Instance.new("TextButton", spamPanel.Chips)
                chip.Size = UDim2.fromOffset(chipWidth, 30)
                chip.Position = UDim2.fromOffset(x, 2)
                chip.BackgroundColor3 = index % 2 == 0 and THEME.Blush or THEME.Lavender
                chip.BackgroundTransparency = 0.08
                chip.Text = ending .. "  x"
                chip.TextColor3 = THEME.Text
                chip.Font = Enum.Font.GothamMedium
                chip.TextSize = 10
                Instance.new("UICorner", chip).CornerRadius = UDim.new(1, 0)
                chip.MouseButton1Click:Connect(function()
                    for removeIndex, savedEnding in ipairs(Config.SpamEndings) do
                        if savedEnding == ending then
                            table.remove(Config.SpamEndings, removeIndex)
                            break
                        end
                    end
                    SaveConfig()
                    AuxUI.RefreshSpamChips()
                    forceUpdateList = true
                    lastInputTime = 0
                end)
                x = x + chipWidth + 7
            end
            spamPanel.Chips.CanvasSize = UDim2.new(0, math.max(0, x - 7), 0, 0)
        end

        AuxUI.AddSpamEnding = function()
            local ending = spamPanel.Input.Text:lower():gsub("’", "'"):gsub("[^a-z'%-]", "")
            if ending == "" then
                ShowToast("Type an ending first", "warning")
                return
            end
            if #ending > 18 then
                ShowToast("Keep an ending at 18 characters or fewer", "warning")
                return
            end
            for _, savedEnding in ipairs(Config.SpamEndings) do
                if savedEnding == ending then
                    ShowToast("That ending is already open", "warning")
                    return
                end
            end
            if #Config.SpamEndings >= 12 then
                ShowToast("Close one ending before adding another", "warning")
                return
            end
            table.insert(Config.SpamEndings, ending)
            spamPanel.Input.Text = ""
            SaveConfig()
            AuxUI.RefreshSpamChips()
            forceUpdateList = true
            lastInputTime = 0
            ShowToast("Opened ending: " .. ending, "success")
        end

        spamPanel.Add.MouseButton1Click:Connect(AuxUI.AddSpamEnding)
        spamPanel.Input.FocusLost:Connect(function(enterPressed)
            if enterPressed then AuxUI.AddSpamEnding() end
        end)
        AuxUI.RefreshSpamChips()
    end

    AuxUI.SyncButtons = function()
        if AuxUI.TrapButton then
            AuxUI.TrapButton.Text = "trap panel  ·  " .. (trapMode and "open" or "closed")
            AuxUI.TrapButton.TextColor3 = trapMode and THEME.Danger or THEME.SubText
        end
        if AuxUI.SpamButton then
            AuxUI.SpamButton.Text = "spam endings  ·  " .. (Config.SpamMode and "open" or "closed")
            AuxUI.SpamButton.TextColor3 = Config.SpamMode and THEME.Accent or THEME.SubText
        end
        if AuxUI.SyncModeRail then AuxUI.SyncModeRail() end
    end

    AuxUI.Responsive = function(viewport)
        viewport = viewport or ((workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(1280, 720))
        local sideScale = math.clamp(math.min((viewport.X - 18) / 366, (viewport.Y - 24) / MAIN_HEIGHT), 0.54, 1)
        AuxUI.TrapPanel.Scale.Scale = sideScale
        AuxUI.SpamPanel.Scale.Scale = sideScale
        if AuxUI.LexiconPanel then
            local lexicon = AuxUI.LexiconPanel
            lexicon.Scale.Scale = math.clamp(math.min((viewport.X - 18) / 470, (viewport.Y - 24) / MAIN_HEIGHT), 0.54, 1)
            if viewport.X >= 900 then
                lexicon.Frame.AnchorPoint = Vector2.new(0, 0.5)
                lexicon.Frame.Position = UDim2.new(0, 16, 0.5, 0)
            else
                lexicon.Frame.AnchorPoint = Vector2.new(0.5, 0.5)
                lexicon.Frame.Position = UDim2.new(0.5, 0, 0.5, 0)
            end
        end

        if viewport.X >= 1260 then
            AuxUI.TrapPanel.Frame.AnchorPoint = Vector2.new(1, 0.5)
            AuxUI.TrapPanel.Frame.Position = UDim2.new(1, -(MAIN_WIDTH + 36), 0.5, 0)
            AuxUI.SpamPanel.Frame.AnchorPoint = Vector2.new(1, 0.5)
            local spamOffset = trapMode and (MAIN_WIDTH + 54 + AuxUI.TrapPanel.Width) or (MAIN_WIDTH + 36)
            AuxUI.SpamPanel.Frame.Position = UDim2.new(1, -spamOffset, 0.5, 0)
        elseif viewport.X >= 760 then
            AuxUI.TrapPanel.Frame.AnchorPoint = Vector2.new(0, 0.5)
            AuxUI.TrapPanel.Frame.Position = UDim2.new(0, 12, 0.5, trapMode and -10 or 0)
            AuxUI.SpamPanel.Frame.AnchorPoint = Vector2.new(0, 0.5)
            AuxUI.SpamPanel.Frame.Position = UDim2.new(0, trapMode and 34 or 12, 0.5, trapMode and 12 or 0)
        else
            AuxUI.TrapPanel.Frame.AnchorPoint = Vector2.new(0.5, 0.5)
            AuxUI.TrapPanel.Frame.Position = UDim2.new(0.5, trapMode and -7 or 0, 0.5, -6)
            AuxUI.SpamPanel.Frame.AnchorPoint = Vector2.new(0.5, 0.5)
            AuxUI.SpamPanel.Frame.Position = UDim2.new(0.5, trapMode and 7 or 0, 0.5, trapMode and 6 or 0)
        end
    end

    local function SetPanelShown(panel, shown)
        if panel.IsShown == shown then return end
        panel.IsShown = shown
        panel.VisibilityToken = (panel.VisibilityToken or 0) + 1
        local token = panel.VisibilityToken
        local targetPosition = panel.Frame.Position
        local tuckedPosition = UDim2.new(
            targetPosition.X.Scale, targetPosition.X.Offset,
            targetPosition.Y.Scale, targetPosition.Y.Offset + 18
        )
        if shown then
            panel.Frame.Visible = true
            panel.Frame.Position = tuckedPosition
            TweenService:Create(panel.Frame, TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                GroupTransparency = 0,
                Position = targetPosition
            }):Play()
        else
            TweenService:Create(panel.Frame, TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.In), {
                GroupTransparency = 1,
                Position = tuckedPosition
            }):Play()
            task.delay(0.23, function()
                if panel.VisibilityToken == token and panel.Frame and panel.Frame.Parent then
                    panel.Frame.Visible = false
                end
            end)
        end
    end

    AuxUI.UpdateVisibility = function(focus)
        AuxUI.Responsive()
        SetPanelShown(AuxUI.TrapPanel, trapMode)
        SetPanelShown(AuxUI.SpamPanel, Config.SpamMode == true)
        AuxUI.SyncButtons()
        local focusedPanel = focus == "trap" and AuxUI.TrapPanel or (focus == "spam" and AuxUI.SpamPanel or nil)
        if focusedPanel and focusedPanel.Frame.Visible then
            focusedPanel.Frame.Parent = nil
            focusedPanel.Frame.Parent = ScreenGui
        end
    end

    local function ApplySideResults(panel, words, meta, detected, highlight, signature)
        if panel.Signature ~= signature then panel.Scroll.CanvasPosition = Vector2.new(0, 0) end
        panel.Words = words
        panel.Meta = meta
        panel.Detected = detected
        panel.Highlight = highlight
        panel.Signature = signature
        panel.Scroll.CanvasSize = UDim2.new(0, 0, 0, math.max(0, #words * 54 - 8))
        panel.Empty.Visible = #words == 0
        if panel.Kind == "spam" and #Config.SpamEndings == 0 then
            panel.Empty.Text = "OPEN YOUR FIRST ENDING\nType it above, then press +"
        elseif panel.Kind == "spam" then
            panel.Empty.Text = "NO MATCHES IN THIS PROMPT\nYour ending collection is still open"
        else
            panel.Empty.Text = "NO RARE PATH ALIGNED\nNo 3-" .. trapSolveCount .. " solve ending for this prompt"
        end
        panel.Count.Text = tostring(#words) .. (panel.Kind == "trap" and (#words == 1 and " trap" or " traps") or (#words == 1 and " match" or " matches"))
        if panel.Kind == "trap" then
            panel.Caption.Text = "RARE PATHS  /  3-" .. trapSolveCount .. " SOLVES"
            panel.Subtitle.Text = "1-4 letter next prompts"
        else
            panel.Caption.Text = tostring(#Config.SpamEndings) .. " CUSTOM " .. (#Config.SpamEndings == 1 and "ENDING" or "ENDINGS")
            panel.Subtitle.Text = "your own ending filters"
        end
        RenderSidePanel(panel)
    end

    -- Side searches now have an explicit scanning state. This lets the main
    -- word garden paint immediately while an uncapped result set is assembled
    -- over several heartbeats.
    AuxUI.BeginSideScan = function(kind, detected, highlight, signature)
        local panel = kind == "trap" and AuxUI.TrapPanel or AuxUI.SpamPanel
        ApplySideResults(panel, {}, {}, detected, highlight, kind .. "|" .. signature)
        panel.Empty.Visible = true
        panel.Empty.Text = kind == "trap"
            and "READING RARE PATHS...\nThe main garden stays ready"
            or "GATHERING ENDINGS...\nThe full collection stays uncapped"
        panel.Count.Text = "scanning..."
    end

    AuxUI.UpdateSideProgress = function(kind, inspected)
        local panel = kind == "trap" and AuxUI.TrapPanel or AuxUI.SpamPanel
        if panel and panel.IsShown then
            panel.Count.Text = tostring(inspected) .. " checked"
        end
    end

    AuxUI.UpdateTrapResults = function(words, meta, detected, highlight, signature)
        ApplySideResults(AuxUI.TrapPanel, words, meta, detected, highlight, "trap|" .. signature)
    end

    AuxUI.UpdateSpamResults = function(words, meta, detected, highlight, signature)
        ApplySideResults(AuxUI.SpamPanel, words, meta, detected, highlight, "spam|" .. signature)
    end

    AuxUI.UpdateSideResults = function(trapWords, trapMeta, spamWords, spamMeta, detected, highlight, signature)
        AuxUI.UpdateTrapResults(trapWords, trapMeta, detected, highlight, signature)
        AuxUI.UpdateSpamResults(spamWords, spamMeta, detected, highlight, signature)
    end

    AuxUI.UpdateVisibility()
end

AuxUI.ApplyFontStyle = function()
    local profile = AuxUI.GetFontProfile()
    Title.Font = profile.Heading
    PromptLetters.Font = profile.Word
    SearchBox.Font = profile.Body
    if AuxUI.FontStyleButton then
        local fontIndex = 1
        for index, name in ipairs(AuxUI.FontStyleOrder) do
            if name == Config.FontStyle then fontIndex = index break end
        end
        AuxUI.FontStyleButton.Text = "word font  ·  " .. Config.FontStyle .. "  (" .. fontIndex .. "/" .. #AuxUI.FontStyleOrder .. ")"
    end
    for _, button in ipairs(ButtonCache) do
        local label = button and button:FindFirstChild("Label")
        if label then label.Font = profile.Word end
    end
    for _, sidePanel in ipairs({AuxUI.TrapPanel, AuxUI.SpamPanel}) do
        if sidePanel then
            sidePanel.Title.Font = profile.Heading
            for _, button in ipairs(sidePanel.RowCache) do
                local label = button and button:FindFirstChild("Label")
                if label then label.Font = profile.Word end
            end
        end
    end
    local lexicon = AuxUI.LexiconPanel
    if lexicon then
        lexicon.Title.Font = profile.Heading
        lexicon.Word.Font = profile.Word
        lexicon.Input.Font = profile.Body
        lexicon.Body.Font = profile.Body
    end
end
AuxUI.ApplyFontStyle()

-- The full result set stays available while only the visible rows are built.
-- This removes the old 40-word cutoff without freezing phones on large lists.
local WordView = {
    matches = {},
    traps = {},
    detected = "",
    highlight = "",
    prefix = "",
    fragment = false,
    backtracked = false,
    signature = ""
}

local function GetWordColumnCount()
    return MainScale and MainScale.Scale >= 0.82 and 2 or 1
end

local function RenderVisibleWordRows()
    local rowHeight = 58
    local columnCount = GetWordColumnCount()
    local firstRow = math.max(1, math.floor(ScrollList.CanvasPosition.Y / rowHeight) + 1)
    local firstIndex = (firstRow - 1) * columnCount + 1
    local poolSize = math.max(12, (math.ceil(ScrollList.AbsoluteSize.Y / rowHeight) + 4) * columnCount)

    for slot = 1, poolSize do
        local i = firstIndex + slot - 1
        local w = WordView.matches[i]
        local btn = ButtonCache[slot]

        if w then
            local trapData = WordView.traps[w]
            local lbl
            if not btn then
                btn = Instance.new("TextButton")
                btn.AnchorPoint = Vector2.new(0.5, 0)
                btn.Size = UDim2.new(0.92, 0, 0, 46)
                btn.BackgroundColor3 = THEME.Surface
                btn.Text = ""
                btn.AutoButtonColor = false
                Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 15)
                do
                    local gradient = Instance.new("UIGradient", btn)
                    gradient.Name = "_aura"
                    gradient.Color = ColorSequence.new({
                        ColorSequenceKeypoint.new(0, THEME.Surface),
                        ColorSequenceKeypoint.new(1, THEME.Lavender)
                    })
                    gradient.Transparency = NumberSequence.new(0.02, 0.34)
                    gradient.Rotation = THEME.Motif == "ember" and 168 or (THEME.Motif == "leaf" and 28 or 12)
                    local outline = Instance.new("UIStroke", btn)
                    outline.Name = "_outline"
                    outline.Color = THEME.Border
                    outline.Transparency = 0.24
                    outline.Thickness = 1
                    local accent = Instance.new("Frame", btn)
                    accent.Name = "_acc"
                    accent.Size = UDim2.fromOffset(4,28)
                    accent.Position = UDim2.new(0,10,0.5,-14)
                    accent.BackgroundColor3 = THEME.Accent
                    accent.BackgroundTransparency = 0.02
                    accent.BorderSizePixel = 0
                    Instance.new("UICorner",accent).CornerRadius = UDim.new(1,0)

                    local sigil = Instance.new("TextLabel", btn)
                    sigil.Name = "_sigil"
                    sigil.Size = UDim2.fromOffset(22,22)
                    sigil.Position = UDim2.new(0,19,0.5,-11)
                    sigil.BackgroundTransparency = 1
                    sigil.Text = THEME.Glyph
                    sigil.TextColor3 = THEME.Accent
                    sigil.Font = Enum.Font.Garamond
                    sigil.TextSize = 17
                end

                lbl = Instance.new("TextLabel", btn)
                lbl.Name = "Label"
                lbl.Size = UDim2.new(1, -110, 1, 0)
                lbl.Position = UDim2.new(0, 47, 0, 0)
                lbl.BackgroundTransparency = 1
                lbl.Font = AuxUI.GetFontProfile().Word
                lbl.TextSize = THEME.Motif == "petal" and 16 or 13
                lbl.TextXAlignment = Enum.TextXAlignment.Left
                lbl.RichText = true

                local rank = Instance.new("TextLabel", btn)
                rank.Name = "Rank"
                rank.Size = UDim2.fromOffset(52, 24)
                rank.Position = UDim2.new(1, -60, 0.5, -12)
                rank.BackgroundColor3 = THEME.Blush
                rank.BackgroundTransparency = 0.22
                rank.TextColor3 = THEME.SubText
                rank.Font = Enum.Font.GothamMedium
                rank.TextSize = 9
                Instance.new("UICorner", rank).CornerRadius = UDim.new(1, 0)

                btn.MouseEnter:Connect(function() Tween(btn, {BackgroundColor3 = THEME.Blush}) end)
                btn.MouseLeave:Connect(function() Tween(btn, {BackgroundColor3 = THEME.Surface}) end)
                btn.MouseButton1Click:Connect(function()
                    local data = ButtonData[btn]
                    if data then
                        SmartType(data.word, data.detected, true)
                        local label = btn:FindFirstChild("Label")
                        if label then label.TextColor3 = THEME.Success end
                        Tween(btn, {BackgroundColor3 = THEME.Sage})
                    end
                end)

                btn.Parent = ScrollList
                table.insert(ButtonCache, btn)
            else
                lbl = btn:FindFirstChild("Label")
                btn.Visible = true
                btn.Parent = ScrollList
                btn.BackgroundColor3 = THEME.Surface
                if lbl then lbl.TextColor3 = THEME.Text end
            end

            local gridRow = math.floor((i - 1) / columnCount)
            local gridColumn = (i - 1) % columnCount
            if columnCount == 2 then
                btn.AnchorPoint = Vector2.new(0, 0)
                btn.Position = UDim2.new(gridColumn * 0.5, gridColumn == 0 and 2 or 6, 0, gridRow * rowHeight)
                btn.Size = UDim2.new(0.5, -8, 0, 50)
            else
                btn.AnchorPoint = Vector2.new(0.5, 0)
                btn.Position = UDim2.new(0.5, 0, 0, gridRow * rowHeight)
                btn.Size = UDim2.new(0.94, 0, 0, 50)
            end
            ButtonData[btn] = {word = w, detected = WordView.detected, trap = trapData}

            local priorityColor = THEME.Accent
            if trapData then priorityColor = THEME.Danger
            elseif i == 1 then priorityColor = THEME.Success
            elseif i == 2 or i == 3 then priorityColor = THEME.Accent2 end

            local aura = btn:FindFirstChild("_aura")
            if aura then
                aura.Enabled = Config.RadiantWords == true
                aura.Color = ColorSequence.new(THEME.Surface, THEME.Surface:Lerp(priorityColor, 0.22))
            end
            local outline = btn:FindFirstChild("_outline")
            if outline then
                outline.Color = Config.RadiantWords and priorityColor or THEME.Border
                outline.Transparency = Config.RadiantWords and ((trapData or i <= 3) and 0.38 or 0.68) or 0.24
            end

            local accentRGB = ColorToRGB(priorityColor)
            local textRGB = ColorToRGB(THEME.Text)
            local highlight = WordView.backtracked and WordView.prefix or WordView.highlight
            if lbl then
                if WordView.fragment and highlight ~= "" then
                    local startAt, endAt = w:find(highlight, 1, true)
                    if startAt then
                        lbl.Text = "<font color=\"rgb(" .. textRGB .. ")\">" .. w:sub(1, startAt - 1) .. "</font>"
                            .. "<font color=\"rgb(" .. accentRGB .. ")\">" .. w:sub(startAt, endAt) .. "</font>"
                            .. "<font color=\"rgb(" .. textRGB .. ")\">" .. w:sub(endAt + 1) .. "</font>"
                    else
                        lbl.Text = w
                    end
                else
                    local prefix = w:sub(1, #highlight)
                    local suffix = w:sub(#highlight + 1)
                    lbl.Text = "<font color=\"rgb(" .. accentRGB .. ")\">" .. prefix .. "</font>"
                        .. "<font color=\"rgb(" .. textRGB .. ")\">" .. suffix .. "</font>"
                end
            end

            local accentDot = btn:FindFirstChild("_acc")
            if accentDot then
                accentDot.BackgroundColor3 = priorityColor
            end
            local rowSigil = btn:FindFirstChild("_sigil")
            if rowSigil then
                rowSigil.Text = trapData and "T" or THEME.Glyph
                rowSigil.TextColor3 = priorityColor
            end

            local rank = btn:FindFirstChild("Rank")
            if rank then
                if trapData then
                    local promptTag = trapData.prompt
                    if #promptTag > 5 then promptTag = ".." .. promptTag:sub(-4) end
                    rank.Text = promptTag .. " · " .. tostring(trapData.count)
                    rank.TextColor3 = THEME.Danger
                    rank.BackgroundColor3 = THEME.Blush
                else
                    rank.Text = string.format("%02d L", #w)
                    rank.TextColor3 = THEME.SubText
                    rank.BackgroundColor3 = i % 2 == 0 and THEME.Blush or THEME.Lavender
                end
            end
        elseif btn then
            btn.Visible = false
            ButtonData[btn] = nil
        end
    end

    for slot = poolSize + 1, #ButtonCache do
        ButtonCache[slot].Visible = false
        ButtonData[ButtonCache[slot]] = nil
    end
end

