local function SideScanIsCurrent(generation)
    return not unloaded and generation == sideScanGeneration
end

local function YieldSideScan(generation, inspected, kind)
    if not SideScanIsCurrent(generation) then return false end
    if inspected > 0 and inspected % SIDE_SCAN_CHUNK == 0 then
        if AuxUI.UpdateSideProgress and inspected % (SIDE_SCAN_CHUNK * 4) == 0 then
            AuxUI.UpdateSideProgress(kind, inspected)
        end
        RunService.Heartbeat:Wait()
    end
    return SideScanIsCurrent(generation)
end

local function FlattenTrapGroups(groups, maxSolveCount, maxWordLength, generation)
    local output = {}
    local written = 0
    for count = 3, maxSolveCount do
        local countGroups = groups[count]
        if countGroups then
            for promptLength = 4, 1, -1 do
                local promptGroups = countGroups[promptLength]
                if promptGroups then
                    for wordLength = 1, maxWordLength do
                        local lengthGroup = promptGroups[wordLength]
                        if lengthGroup then
                            for _, word in ipairs(lengthGroup) do
                                written = written + 1
                                output[written] = word
                                if not YieldSideScan(generation, written, "trap") then return nil end
                            end
                        end
                    end
                end
            end
        end
    end
    return output
end

local function FlattenSpamGroups(groups, endingCount, maxWordLength, generation)
    local output = {}
    local written = 0
    for rank = 1, endingCount do
        local rankGroups = groups[rank]
        if rankGroups then
            for wordLength = 1, maxWordLength do
                local lengthGroup = rankGroups[wordLength]
                if lengthGroup then
                    for _, word in ipairs(lengthGroup) do
                        written = written + 1
                        output[written] = word
                        if not YieldSideScan(generation, written, "spam") then return nil end
                    end
                end
            end
        end
    end
    return output
end

-- Trap and Spam are intentionally computed away from UpdateList. Both retain
-- every qualifying result, but a new prompt cancels obsolete work before it
-- can overwrite the current panels.
local function StartBackgroundSideScans(matches, bucket, searchPrefix, detectedText, highlight, isBacktracked, fragmentMode)
    sideScanGeneration = sideScanGeneration + 1
    local generation = sideScanGeneration
    local solveLimit = trapSolveCount
    local scanBucket = fragmentMode and matches or bucket
    local scanPrefix = fragmentMode and "" or searchPrefix
    local trapEnabled = trapMode and not isBacktracked and #matches > 0
    local spamEnabled = Config.SpamMode == true and not isBacktracked and #Config.SpamEndings > 0
    local baseSignature = searchPrefix .. "|" .. sortMode .. "|" .. suffixMode .. "|" .. tostring(lengthMode)
        .. "|" .. tostring(solveLimit) .. "|" .. table.concat(Config.SpamEndings, ",") .. "|" .. tostring(fragmentMode)

    trapScanPending = trapEnabled

    if trapMode then
        if trapEnabled and AuxUI.BeginSideScan then
            AuxUI.BeginSideScan("trap", detectedText, highlight, baseSignature)
        elseif AuxUI.UpdateTrapResults then
            AuxUI.UpdateTrapResults({}, {}, detectedText, highlight, baseSignature)
        end
    end

    if Config.SpamMode == true then
        if spamEnabled and AuxUI.BeginSideScan then
            AuxUI.BeginSideScan("spam", detectedText, highlight, baseSignature)
        elseif AuxUI.UpdateSpamResults then
            AuxUI.UpdateSpamResults({}, {}, detectedText, highlight, baseSignature)
        end
    end

    if trapEnabled then
        task.spawn(function()
            RunService.Heartbeat:Wait()
            if not SideScanIsCurrent(generation) then return end

            local trapGroups = {}
            local trapMeta = {}
            local maxWordLength = 0

            for index, word in ipairs(matches) do
                local chosenPrompt = nil
                local chosenCount = nil

                for suffixLength = math.min(4, #word), 1, -1 do
                    local nextPrompt = word:sub(-suffixLength)
                    local solveCount = PrefixLiveCounts[nextPrompt] or 0
                    if word:sub(1, #nextPrompt) == nextPrompt and solveCount > 0 then
                        solveCount = solveCount - 1
                    end
                    if solveCount >= 3 and solveCount <= solveLimit then
                        if not chosenCount or solveCount < chosenCount then
                            chosenPrompt = nextPrompt
                            chosenCount = solveCount
                        end
                    end
                end

                if chosenPrompt then
                    trapMeta[word] = {prompt = chosenPrompt, count = chosenCount}
                    trapGroups[chosenCount] = trapGroups[chosenCount] or {}
                    local countGroups = trapGroups[chosenCount]
                    local promptLength = #chosenPrompt
                    countGroups[promptLength] = countGroups[promptLength] or {}
                    local promptGroups = countGroups[promptLength]
                    local wordLength = #word
                    promptGroups[wordLength] = promptGroups[wordLength] or {}
                    local lengthGroup = promptGroups[wordLength]
                    lengthGroup[#lengthGroup + 1] = word
                    if wordLength > maxWordLength then maxWordLength = wordLength end
                end

                if not YieldSideScan(generation, index, "trap") then return end
            end

            local trapWords = FlattenTrapGroups(trapGroups, solveLimit, maxWordLength, generation)
            if not trapWords or not SideScanIsCurrent(generation) then return end

            trapScanPending = false
            currentBestMatch = (trapMode and trapWords[1]) or matches[1]
            if AuxUI.UpdateTrapResults then
                AuxUI.UpdateTrapResults(trapWords, trapMeta, detectedText, highlight, baseSignature)
            end

            if trapMode then
                if #trapWords > 0 then
                    local firstTrap = trapMeta[trapWords[1]]
                    StatusText.Text = "trap ready · " .. trapWords[1] .. " > " .. firstTrap.prompt .. " · " .. firstTrap.count .. " solves"
                    StatusText.TextColor3 = THEME.Danger
                    Tween(StatusDot, {BackgroundColor3 = THEME.Accent2})
                else
                    StatusText.Text = "trap scan · no 3-" .. solveLimit .. " solve ending found"
                    StatusText.TextColor3 = THEME.SubText
                    Tween(StatusDot, {BackgroundColor3 = THEME.SubText})
                end
            end
        end)
    end

    if spamEnabled then
        local endings = {}
        for index, ending in ipairs(Config.SpamEndings) do endings[index] = ending end

        task.spawn(function()
            RunService.Heartbeat:Wait()
            if not SideScanIsCurrent(generation) then return end

            local endingRank = {}
            local endingsByLastLetter = {}
            for rank, ending in ipairs(endings) do
                endingRank[ending] = rank
                local lastLetter = ending:sub(-1)
                endingsByLastLetter[lastLetter] = endingsByLastLetter[lastLetter] or {}
                local group = endingsByLastLetter[lastLetter]
                group[#group + 1] = ending
            end

            local spamGroups = {}
            local spamMeta = {}
            local maxWordLength = 0
            local inspected = 0
            local startIndex = 1
            local canScan = scanBucket ~= nil and not scanPrefix:find("#", 1, true) and not scanPrefix:find("*", 1, true)
            if canScan and #scanPrefix > 0 then
                startIndex = BinarySearchStart(scanBucket, scanPrefix)
                canScan = startIndex ~= -1
            end

            if canScan then
                for index = startIndex, #scanBucket do
                    local word = scanBucket[index]
                    if #scanPrefix > 0 and word:sub(1, #scanPrefix) ~= scanPrefix then break end
                    inspected = inspected + 1

                    if not Blacklist[word] and not UsedWords[word] then
                        local possibleEndings = endingsByLastLetter[word:sub(-1)]
                        local chosenEnding = nil
                        if possibleEndings then
                            for _, ending in ipairs(possibleEndings) do
                                if #word >= #ending and word:sub(-#ending) == ending then
                                    if not chosenEnding or #ending > #chosenEnding then chosenEnding = ending end
                                end
                            end
                        end

                        if chosenEnding then
                            local allowHyphen = searchPrefix:find("-", 1, true) or chosenEnding:find("-", 1, true)
                            local allowApostrophe = searchPrefix:find("'", 1, true) or chosenEnding:find("'", 1, true)
                            local punctuationAllowed = (not word:find("-", 1, true) or allowHyphen)
                                and (not word:find("'", 1, true) or allowApostrophe)
                                and (not word:find("’", 1, true) or allowApostrophe)

                            if punctuationAllowed then
                                spamMeta[word] = chosenEnding
                                local rank = endingRank[chosenEnding]
                                spamGroups[rank] = spamGroups[rank] or {}
                                local rankGroups = spamGroups[rank]
                                local wordLength = #word
                                rankGroups[wordLength] = rankGroups[wordLength] or {}
                                local lengthGroup = rankGroups[wordLength]
                                lengthGroup[#lengthGroup + 1] = word
                                if wordLength > maxWordLength then maxWordLength = wordLength end
                            end
                        end
                    end

                    if not YieldSideScan(generation, inspected, "spam") then return end
                end
            end

            local spamWords = FlattenSpamGroups(spamGroups, #endings, maxWordLength, generation)
            if not spamWords or not SideScanIsCurrent(generation) then return end
            if Config.SpamMode == true and AuxUI.UpdateSpamResults then
                AuxUI.UpdateSpamResults(spamWords, spamMeta, detectedText, highlight, baseSignature)
            end
        end)
    end
end

UpdateList = function(detectedText, requiredLetter)
    detectedText = AuxUI.NormalizeWordText(detectedText)
    if requiredLetter then
        requiredLetter = AuxUI.NormalizeWordText(requiredLetter)
    end
    local matches = {}
    local searchPrefix = detectedText
    local isBacktracked = false
    local manualSearch = false

    if SearchBox and SearchBox.Text ~= "" then
        local typedPrefix = AuxUI.NormalizeWordText(SearchBox.Text)
        if typedPrefix ~= "" then
            searchPrefix = typedPrefix
            manualSearch = true
            if requiredLetter and searchPrefix:sub(1,1) ~= requiredLetter:sub(1,1):lower() then
                 requiredLetter = nil
            end
        end
    end

    if not manualSearch and requiredLetter and #requiredLetter > 0 then
        local reqLen = GetMatchLength(requiredLetter, searchPrefix)
        if reqLen == #searchPrefix and #requiredLetter > #searchPrefix then
             searchPrefix = requiredLetter
        end
    end
    
    local bucket = AuxUI.GetSearchBucket(searchPrefix ~= "" and searchPrefix or requiredLetter)
    local punctuationFragment = false

    local function CollectMatches(prefix, tryFallbackLengths)
        local exacts = {}
        local fallbackExacts = {}
        local partials = {}
        local maxPartialLen = 0
        
        if bucket then
            local checkWord = function(w)
                if Blacklist[w] or UsedWords[w] then return end
                local mLen = GetMatchLength(w, prefix)
                if not PassesPunctuationFilter(w, prefix) then return end
                
                -- Check for main list filtering (suffix/length)
                if suffixMode ~= "" and w:sub(-#suffixMode) ~= suffixMode then return end
                
                local isLengthMatch = true
                if not tryFallbackLengths and lengthMode > 0 then
                    isLengthMatch = (#w == lengthMode)
                elseif tryFallbackLengths and lengthMode > 0 then
                     isLengthMatch = true
                end
                
                if not isLengthMatch then return end

                if mLen == #prefix then
                    table.insert(exacts, w)
                elseif #exacts == 0 then
                    if mLen > maxPartialLen then
                        maxPartialLen = mLen
                        partials = {w}
                    elseif mLen == maxPartialLen and mLen > 0 then
                        if #partials < 50 then table.insert(partials, w) end
                    end
                end
            end

            local useBinary = true
            if prefix:find("#") or prefix:find("%*") then useBinary = false end
            
            if useBinary and #prefix > 0 then
                local startIndex = BinarySearchStart(bucket, prefix)
                
                if startIndex ~= -1 then
                    for i = startIndex, #bucket do
                        local w = bucket[i]
                        
                        if w:sub(1, #prefix) ~= prefix then break end
                        
                        checkWord(w)
                    end
                end
            else
                for _, w in ipairs(bucket) do
                    checkWord(w)
                end
            end
            
            if sortMode == "Random" and #exacts > 0 then
                shuffleTable(exacts)
            end
        end
        return exacts, partials, maxPartialLen
    end

    local exacts, partials, pLen = CollectMatches(searchPrefix, false)

    if #exacts == 0 and lengthMode > 0 then
        local fallbackExacts, fallbackPartials, fallbackPLen = CollectMatches(searchPrefix, true)
        if #fallbackExacts > 0 then
             exacts = fallbackExacts
        end
    end

    -- A punctuation-only HUD tile ("-" or "'") is not a useful alphabetical
    -- first character. If no literal prefix exists, show every unused word that
    -- contains that exact punctuation fragment. The scan stays inside the tiny
    -- punctuation index and the clicked row still corrects the whole game box.
    if #exacts == 0 and (searchPrefix:find("-", 1, true) or searchPrefix:find("'", 1, true)) then
        local punctuationWords = searchPrefix:find("-", 1, true)
            and AuxUI.PunctuationBuckets.Hyphen or AuxUI.PunctuationBuckets.Apostrophe
        local function CollectFragments(ignoreLength)
            local found = {}
            for _, word in ipairs(punctuationWords) do
                if not Blacklist[word] and not UsedWords[word]
                    and word:find(searchPrefix, 1, true)
                    and (suffixMode == "" or word:sub(-#suffixMode) == suffixMode)
                    and (ignoreLength or lengthMode <= 0 or #word == lengthMode)
                    and PassesPunctuationFilter(word, searchPrefix) then
                    found[#found + 1] = word
                end
            end
            return found
        end
        exacts = CollectFragments(false)
        if #exacts == 0 and lengthMode > 0 then exacts = CollectFragments(true) end
        if #exacts > 0 then
            punctuationFragment = true
            partials = {}
            pLen = 0
            if sortMode == "Random" then shuffleTable(exacts) end
        end
    end

    if #exacts > 0 then
        matches = exacts
    elseif pLen > 0 then
        matches = partials
        searchPrefix = searchPrefix:sub(1, pLen)
        isBacktracked = true
    elseif requiredLetter and #requiredLetter > 0 then
        local reqChar = requiredLetter:sub(1,1):lower()
        if searchPrefix:sub(1,1):lower() ~= reqChar then
            local fallbackBucket = AuxUI.GetSearchBucket(requiredLetter)
            if fallbackBucket then
                for _, w in ipairs(fallbackBucket) do
                    if not Blacklist[w] and not UsedWords[w] and PassesPunctuationFilter(w, requiredLetter) then
                         local mLen = GetMatchLength(w, requiredLetter)
                         if mLen == #requiredLetter then
                             table.insert(matches, w)
                         end
                    end
                end
            end
            
            if #matches > 0 then
                searchPrefix = requiredLetter
                bucket = fallbackBucket
                isBacktracked = true
            end
        end
    end
    
    if #matches > 0 then
        if sortMode == "Longest" then
            SortByLengthFast(matches, true)
        elseif sortMode == "Shortest" then
            SortByLengthFast(matches, false)
        elseif sortMode == "Killer" then
            SortKillerFast(matches)
        elseif sortMode == "Hyphen" then
            SortByLengthFast(matches, false)
        elseif sortMode == "Apostrophe" then
            SortByLengthFast(matches, false)
        end
    end

    local displayList = matches
    
    if showKeyboard and KeyboardFrame.Visible then
        local colors = {THEME.Success, THEME.Accent2, THEME.Accent}
        
        local targetKeys = {}

        for i = 1, math.min(3, #displayList) do
            local w = displayList[i]
            local nextChar = w:sub(#searchPrefix + 1, #searchPrefix + 1)
            if nextChar and nextChar ~= "" then
                local char = nextChar:lower()
                if not targetKeys[char] then
                    targetKeys[char] = i
                end
            end
        end

        for char, k in pairs(Keys) do
            local priority = targetKeys[char]
            if priority then
                k.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
                Tween(k, {BackgroundColor3 = colors[priority]}, 0.3)
            else
                Tween(k, {BackgroundColor3 = THEME.Lavender}, 0.2)
            end
        end
    end

    if #matches > 0 and not isBacktracked then
        currentBestMatch = matches[1]
    else
        currentBestMatch = nil
    end
    
    if punctuationFragment then
        StatusText.Text = (searchPrefix:find("-", 1, true) and "hyphen" or "apostrophe")
            .. " vault · " .. tostring(#matches) .. " complete paths"
        StatusText.TextColor3 = THEME.Danger
        Tween(StatusDot, {BackgroundColor3 = THEME.Danger})
    elseif isBacktracked then
        local validPart = searchPrefix
        local invalidPart = detectedText:sub(#searchPrefix + 1)
        local accentRGB = ColorToRGB(THEME.Accent)
        StatusText.Text = "closest " .. THEME.One .. ": <font color=\"rgb(" .. accentRGB .. ")\">" .. validPart .. "</font><font color=\"rgb(190,105,132)\">" .. invalidPart .. "</font>"
        StatusText.TextColor3 = THEME.SubText
    elseif #exacts == 0 and lengthMode > 0 and suffixMode ~= "" then
         StatusText.Text = "no exact length — showing nearby words"
         StatusText.TextColor3 = THEME.Warning
    end

    if trapMode and not isBacktracked then
        StatusText.Text = #matches > 0 and "trap oracle · reading rare paths..."
            or ("trap scan · no 3-" .. trapSolveCount .. " solve ending found")
        StatusText.TextColor3 = #matches > 0 and THEME.Danger or THEME.SubText
        Tween(StatusDot, {BackgroundColor3 = #matches > 0 and THEME.Accent2 or THEME.SubText})
    end

    if ResultCount then
        local shownCount = tostring(#matches):reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "")
        local loadedCount = tostring(#Words):reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "")
        ResultCount.Text = shownCount .. " paths  /  " .. loadedCount .. " words"
    end

    if ListCaption then
        ListCaption.Text = "WORD CONSTELLATION"
    end

    local signature = searchPrefix .. "|" .. sortMode .. "|" .. suffixMode .. "|" .. tostring(lengthMode)
        .. "|fragment=" .. tostring(punctuationFragment)
        .. "|main"
    if WordView.signature ~= signature then
        ScrollList.CanvasPosition = Vector2.new(0, 0)
    end
    WordView.matches = displayList
    WordView.traps = {}
    WordView.detected = detectedText
    WordView.highlight = manualSearch and searchPrefix or detectedText
    WordView.prefix = searchPrefix
    WordView.fragment = punctuationFragment
    WordView.backtracked = isBacktracked
    WordView.signature = signature
    local wordColumns = GetWordColumnCount()
    local wordRows = math.ceil(#displayList / wordColumns)
    ScrollList.CanvasSize = UDim2.new(0, 0, 0, math.max(0, wordRows * 58 - 8))
    RenderVisibleWordRows()
    local sideHighlight = manualSearch and searchPrefix or detectedText
    StartBackgroundSideScans(matches, bucket, searchPrefix, detectedText, sideHighlight, isBacktracked, punctuationFragment)
end

