runConn = RunService.RenderStepped:Connect(function()
    local success, err = pcall(function()
        local now = tick()
        if now - lastLogicUpdate < LOGIC_RATE then return end
        lastLogicUpdate = now
        local player = Players.LocalPlayer
        local gui = player and player:FindFirstChild("PlayerGui")
        local frame = gui and gui:FindFirstChild("InGame") and gui.InGame:FindFirstChild("Frame")

        if isTyping and (tick() - lastTypingStart) > 15 then
            isTyping = false
            CancelAutoPlaySchedule()
            StatusText.Text = "typing gently reset"
            StatusText.TextColor3 = THEME.Warning
        end
        
        local isVisible = false
        if frame and frame.Parent then
            if frame.Parent:IsA("ScreenGui") then
                isVisible = frame.Parent.Enabled
            elseif frame.Parent:IsA("GuiObject") then
                isVisible = frame.Parent.Visible
            end
        end

        local seconds = nil
        if isVisible then
            local circle = frame:FindFirstChild("Circle")
            local timerLbl = circle and circle:FindFirstChild("Timer") and circle.Timer:FindFirstChild("Seconds")
            
            if timerLbl then
                local timeText = timerLbl.Text
                seconds = tonumber(timeText:match("([%d%.]+)"))
                
                StatsData.Frame.Visible = true
                StatsData.Timer.Text = timeText
                if seconds and seconds < 3 then StatsData.Timer.TextColor3 = THEME.Danger
                else StatsData.Timer.TextColor3 = THEME.Text end
            end
        else
            StatsData.Frame.Visible = false
        end

        local isMyTurn, requiredLetter = GetTurnInfo(frame)
        if AuxUI.SetGuardianMotionActive then
            AuxUI.SetGuardianMotionActive(ScreenGui.Enabled and (not isVisible or not isMyTurn))
        end
        
        local wordPollRate = (isMyTurn or Config.TurnAwarePerformance == false) and 0.04 or 0.14
        if (now - lastWordCheck) > wordPollRate then
            cachedDetected, cachedCensored = GetCurrentGameWord(frame)
            lastWordCheck = now
        end
        local detected, censored = cachedDetected, cachedCensored
        local manualSearchOpen = SearchBox and SearchBox.Text ~= ""
        local becameMyTurn = isMyTurn and not AuxUI.LastWasMyTurn
        local leftMyTurn = AuxUI.LastWasMyTurn and not isMyTurn

        if Config.TurnAwarePerformance ~= false and leftMyTurn and not manualSearchOpen then
            AuxUI.SubmissionVerifyGeneration = (AuxUI.SubmissionVerifyGeneration or 0) + 1
            sideScanGeneration = sideScanGeneration + 1
            trapScanPending = false
            listUpdatePending = false
            currentBestMatch = nil
            CancelAutoPlaySchedule()
            forceUpdateList = false
        elseif becameMyTurn then
            -- One coalesced rebuild is enough when the new prompt settles.
            AuxUI.SubmissionVerifyGeneration = (AuxUI.SubmissionVerifyGeneration or 0) + 1
            AuxUI.SubmittedPromptSignature = nil
            lastDetected = "---"
            lastRequiredLetter = ""
            listUpdatePending = true
            lastInputTime = now
        end
        AuxUI.LastWasMyTurn = isMyTurn
        local allowAutomaticRefresh = Config.TurnAwarePerformance == false or isMyTurn or manualSearchOpen

        local visualPrompt = censored and "?" or (detected ~= "" and detected or requiredLetter)
        if not isVisible then visualPrompt = THEME.Glyph end
        if visualPrompt == nil or visualPrompt == "" then visualPrompt = "—" end
        visualPrompt = string.upper(tostring(visualPrompt))
        local punctuationPrompt = visualPrompt:find("-", 1, true) ~= nil or visualPrompt:find("'", 1, true) ~= nil
        local targetPromptFont = punctuationPrompt and Enum.Font.Code or AuxUI.GetFontProfile().Word
        local targetPromptColor = punctuationPrompt and Color3.fromRGB(255, 250, 247) or THEME.Surface
        local targetOracleText = punctuationPrompt
            and "PUNCTUATION PROMPT   /   FULL HYPHEN + APOSTROPHE VAULT OPEN"
            or "LIVE PROMPT   /   YOUR CLICK IS THE ONLY COMMAND"
        local targetOracleColor = punctuationPrompt and THEME.Danger or THEME.Accent
        if PromptLetters.Font ~= targetPromptFont then PromptLetters.Font = targetPromptFont end
        if PromptLetters.TextColor3 ~= targetPromptColor then PromptLetters.TextColor3 = targetPromptColor end
        if OracleCaption.Text ~= targetOracleText then OracleCaption.Text = targetOracleText end
        if OracleCaption.TextColor3 ~= targetOracleColor then OracleCaption.TextColor3 = targetOracleColor end
        if PromptLetters.Text ~= visualPrompt then
            PromptLetters.Text = visualPrompt
            PromptLetters.TextTransparency = 0.65
            TweenService:Create(PromptLetters, TweenInfo.new(0.26, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                TextTransparency = 0
            }):Play()
        end

        -- Last-second submission is never implicit. It requires both the
        -- Auto Play master switch and the separate last-second save switch.
        local submissionGuarded = AuxUI.SubmittedPromptSignature == detected and (now - AuxUI.LastSubmissionAt) < 0.9
        if autoPlay and panicMode and isVisible and isMyTurn and not isTyping and not submissionGuarded and seconds and seconds < 1.5 then
            local char = (requiredLetter or ""):sub(1, 1):lower()
            local bucket = Buckets[char]
            if bucket then
                local bestWord = currentBestMatch
                if not bestWord or Blacklist[bestWord] or UsedWords[bestWord] or bestWord:sub(1, #detected) ~= detected then
                    bestWord = nil
                    local bestLen = 999
                    local startIndex = BinarySearchStart(bucket, detected)
                    if startIndex ~= -1 then
                        for index = startIndex, #bucket do
                            local w = bucket[index]
                            if w:sub(1, #detected) ~= detected then break end
                            if not Blacklist[w] and not UsedWords[w] and #w < bestLen then
                                bestWord = w
                                bestLen = #w
                            end
                        end
                    end
                end
                
                if bestWord then
                    StatusText.Text = "quick save found"
                    StatusText.TextColor3 = THEME.Danger
                    CancelAutoPlaySchedule()
                    SmartType(bestWord, detected, false, false, true, detected)
                end
            end
        end

        if autoJoin and (now - lastAutoJoinCheck > AUTO_JOIN_RATE) then
            lastAutoJoinCheck = now
            task.spawn(function()
                local displayMatch = gui and gui:FindFirstChild("DisplayMatch")
                local dFrame = displayMatch and displayMatch:FindFirstChild("Frame")
                local matches = dFrame and dFrame:FindFirstChild("Matches")
                
                if matches then
                    for _, matchFrame in ipairs(matches:GetChildren()) do
                        if (matchFrame:IsA("Frame") or matchFrame:IsA("GuiObject")) and matchFrame.Name ~= "UIListLayout" then
                            local joinBtn = matchFrame:FindFirstChild("Join")
                            local title = matchFrame:FindFirstChild("Title")
                            
                            local isLastLetter = false
                            local titleText = "N/A"
                            if title and title:IsA("TextLabel") then
                                titleText = title.Text
                                if titleText:find("Last Letter") then
                                    isLastLetter = true
                                end
                            end

                            local idx = tonumber(matchFrame.Name)
                            local allowed = true
                            if idx then
                                if idx >= 1 and idx <= 4 then allowed = Config.AutoJoinSettings._1v1
                                elseif idx >= 5 and idx <= 8 then allowed = Config.AutoJoinSettings._4p
                                elseif idx == 9 then allowed = Config.AutoJoinSettings._8p
                                end
                            end

                            if joinBtn and joinBtn.Visible and isLastLetter and allowed then
                                local matchId = matchFrame.Name
                                if (tick() - (JoinDebounce[matchId] or 0)) > 2 then
                                    JoinDebounce[matchId] = tick()
                                    task.wait(0.5)
                                    
                                    local clicked = false
                                    if getconnections then
                                        if joinBtn:IsA("GuiButton") then
                                            local success, conns = pcall(function() return getconnections(joinBtn.MouseButton1Click) end)
                                            if success and conns then
                                                for _, conn in ipairs(conns) do
                                                    if conn.Fire then conn:Fire() end
                                                    if conn.Function then
                                                        task.spawn(conn.Function)
                                                    end
                                                    clicked = true
                                                end
                                            end
                                        end
                                    end
                                    
                                    if not clicked then
                                        local cd = joinBtn:FindFirstChildWhichIsA("ClickDetector")
                                        if cd then
                                            fireclickdetector(cd)
                                            clicked = true
                                        end
                                    end

                                    if not clicked then
                                        local absPos = joinBtn.AbsolutePosition
                                        local absSize = joinBtn.AbsoluteSize
                                        local centerX = absPos.X + absSize.X/2
                                        local centerY = absPos.Y + absSize.Y/2
                                        
                                        VirtualInputManager:SendMouseButtonEvent(centerX, centerY, 0, true, game, 1)
                                        task.wait(0.05)
                                        VirtualInputManager:SendMouseButtonEvent(centerX, centerY, 0, false, game, 1)
                                    end
                                    break
                                end
                            end
                        end
                    end
                end
            end)
        end

        local typeLbl = frame and frame:FindFirstChild("Type")
        local typeVisible = typeLbl and typeLbl.Visible
        if typeVisible and not lastTypeVisible then
            StatusText.Text = "a new round has begun"
            StatusText.TextColor3 = THEME.Accent
        end
        lastTypeVisible = typeVisible
        if censored then
            if StatusText.Text ~= "the word is hidden" then
                StatusText.Text = "the word is hidden"
                StatusText.TextColor3 = THEME.Warning
                Tween(StatusDot, {BackgroundColor3 = THEME.Warning})
                
                for _, btn in ipairs(ButtonCache) do btn.Visible = false end
                StatsData.Count.Text = "0 " .. THEME.Many
            end
            
            listUpdatePending = false
            forceUpdateList = false
            currentBestMatch = nil
            lastDetected = detected
            lastRequiredLetter = requiredLetter
        end
        
        if allowAutomaticRefresh and listUpdatePending and not isTyping and (now - lastInputTime > LIST_DEBOUNCE) then
            -- Never paint a queued result set if the detector has already
            -- moved to another prompt. The state branch below will queue the
            -- newest prompt on this same logic tick.
            if detected == lastDetected and (requiredLetter or "") == (lastRequiredLetter or "") then
                listUpdatePending = false
                UpdateList(lastDetected, lastRequiredLetter)
                StatsData.Count.Text = tostring(#WordView.matches) .. " " .. (#WordView.matches == 1 and THEME.One or THEME.Many)
            else
                listUpdatePending = false
            end
        end

        if not isVisible then
            if StatusText.Text ~= "resting between rounds" then
                StatusText.Text = "resting between rounds"
                StatusText.TextColor3 = THEME.SubText
                Tween(StatusDot, {BackgroundColor3 = THEME.SubText})
                for _, btn in ipairs(ButtonCache) do btn.Visible = false end
                StatsData.Count.Text = "0 " .. THEME.Many
            end
            lastDetected = "---"
        elseif Config.TurnAwarePerformance ~= false and not isMyTurn and not manualSearchOpen then
            -- Opponent turns still record completed words, but never rebuild
            -- the main, trap, or spam collections. This is the handoff fast path.
            if not isTyping and detected ~= "" and detected ~= lastDetected and #detected > 2 then
                local first = detected:sub(1, 1)
                local completedBucket = first ~= "#" and Buckets and Buckets[first]
                if completedBucket then
                    local completedIndex = BinarySearchStart(completedBucket, detected)
                    if completedIndex ~= -1 and completedBucket[completedIndex] == detected then
                        RemoveRuntimeWord(detected)
                    end
                end
            end
            if detected ~= lastDetected or requiredLetter ~= lastRequiredLetter then
                lastDetected = detected
                lastRequiredLetter = requiredLetter
                StatusText.Text = "observing the opponent · solvers resting"
                StatusText.TextColor3 = THEME.SubText
                Tween(StatusDot, {BackgroundColor3 = THEME.SubText})
            end
        elseif not isTyping and (detected ~= lastDetected or requiredLetter ~= lastRequiredLetter or forceUpdateList) then
            if detected ~= lastDetected or requiredLetter ~= lastRequiredLetter then
                CancelAutoPlaySchedule()
            end
            currentBestMatch = nil
            lastDetected = detected
            lastRequiredLetter = requiredLetter
            
            if detected == "" and not forceUpdateList then
                StatusText.Text = "waiting for a little word..."
                StatusText.TextColor3 = THEME.SubText
                Tween(StatusDot, {BackgroundColor3 = THEME.SubText})
                
                UpdateList("", requiredLetter)
                listUpdatePending = false
                StatsData.Count.Text = tostring(#WordView.matches) .. " " .. (#WordView.matches == 1 and THEME.One or THEME.Many)
            else
                if detected ~= "" then
                    local isCompleted = false
                    if #detected > 2 then
                        local c = detected:sub(1,1)
                        local completedBucket = c ~= "#" and Buckets and Buckets[c]
                        if completedBucket then
                            local completedIndex = BinarySearchStart(completedBucket, detected)
                            isCompleted = completedIndex ~= -1 and completedBucket[completedIndex] == detected
                        end
                    end

                    if isCompleted then
                        RemoveRuntimeWord(detected)
                        StatusText.Text = "used word: " .. detected .. "  ✓"
                        StatusText.TextColor3 = THEME.Success
                        Tween(StatusDot, {BackgroundColor3 = THEME.Success})
                    else
                        StatusText.Text = "current letters: " .. detected
                        StatusText.TextColor3 = THEME.Accent
                        Tween(StatusDot, {BackgroundColor3 = THEME.Warning})
                    end
                end
                
                if forceUpdateList then
                    listUpdatePending = true
                    lastInputTime = 0
                    forceUpdateList = false
                else
                    listUpdatePending = true
                    lastInputTime = now
                end
            end
        end

        if autoPlay and not submissionGuarded and not (trapMode and trapScanPending) and not isTyping and not isAutoPlayScheduled and currentBestMatch and detected == lastDetected then
            local isMyTurnCheck, _ = GetTurnInfo(frame)
            if isMyTurnCheck then
                local targetWord = currentBestMatch
                local snapshotDetected = lastDetected
                local snapshotRequired = requiredLetter or ""
                ScheduleAutoPlay(targetWord, snapshotDetected, snapshotRequired)
            end
        end
    end)
end)

inputConn = UserInputService.InputBegan:Connect(function(input)
    if unloaded then return end
    if input.KeyCode == TOGGLE_KEY then ScreenGui.Enabled = not ScreenGui.Enabled end
end)

__lrrxSetStage("08  Ready", false)
if FinishBootTransition then FinishBootTransition(MainFrame) end
end

local __lrrxOk, __lrrxError = xpcall(__lrrxMain, function(err)
    local message = tostring(err)
    pcall(function()
        if debug and type(debug.traceback) == "function" then
            message = debug.traceback(message, 2)
        end
    end)
    return message
end)

if __lrrxOk then
    task.delay(0.35, function()
        if __lrrxDiagnosticGui then __lrrxDiagnosticGui:Destroy() end
    end)
else
    if __lrrxDiagnosticGui then __lrrxDiagnosticGui.Enabled = true end
    __lrrxSetStage(__lrrxError, true)
    pcall(function() warn("[LRRXWARE] " .. tostring(__lrrxError)) end)
end
